import {restoreSections} from './section-state.js';
import {connectLive} from './live-updates.js';
import {CATEGORIES as categories,EXPENSE_CATEGORIES,TYPES,TYPE_BY_NAME,typeSlug,typeColors} from './categories.js';
import {buildPlan,forecastReconciliation} from './plan-view.js';
import {calculateScenario} from './scenario.js';
import {tripCost,evaluateTrip,starterTripEstimate,suggestTripDates,automaticTripSaving} from './trip-planner.js';
import {reviewState,weekStart,changeDescription,tripFieldVisible,attentionItems,scheduleGaps} from './workflow.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n)||0),add=(d,n)=>new Date(Date.parse(d+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const freq=['One-time','Weekly','Biweekly','Monthly','Quarterly','Yearly'];
let B,S,activeVersion='Unavailable',page='home',calendarMonth='',calendarEvents=[],calendarRecordedEvents=[],saveHandler=null,focusBefore=null,renderVersion=0;
const pages={home:'Home',calendar:'Calendar',recurring:'Recurring',plan:'Plan',debt:'Debt',goals:'Goals',transactions:'Transactions',reports:'Reports',settings:'Settings',annual:'Annual Planner',surprise:'Surprise',income:'Income',insights:'Insights'};
function actionLabel(label,action=''){
 if(typeof label!=='string'||label.includes('<svg'))return label;
const icon=/\bedit\b/i.test(label)&&action==='account'&&page==='debt'?'edit':/\b(delete|remove)\b/i.test(label)?'trash':'';
 return icon?uiIcon(icon).replace('class="ui-icon"','class="ui-icon action-icon"')+label:label;
}
const btn=(label,action,id='',extra='',cls='')=>`<button class="${cls||'secondary'}" data-action="${action}" data-id="${esc(id)}" ${extra}>${actionLabel(label,action)}</button>`;
const fold=(title,body)=>`<details class="compact-section"><summary>${title}</summary>${body}</details>`;
function restoreDisplay(root,scope){let storage;try{storage=localStorage;}catch{}restoreSections(root,(B?.sampleMode?'sample:':'real:')+scope,storage);if(scope==='page:transactions'&&location.hash.includes('focus=other')){const section=root?.querySelector?.('[data-section-key="tools-review-warning"]');if(section)section.open=true;}}
const helpText={allocation:'Paycheck allocation groups existing bills between paydays. It creates no new deductions. Same-day paychecks are combined. The lowest amount above buffer already accounts for your cash, scheduled bills and reserved savings.',needs:'Each need is checked individually. Scheduling one adds it to Calendar and recalculates the dates for the others. High priority searches 30 days, Medium 90, and Low 180. Longer forecasts depend on your entered schedules.',savings:'Saved money is already in your cash accounts and is reserved for this target once. Weekly savings amounts are suggestions; they do not transfer money or create expenses.'};
const help=(id)=>btn('ⓘ','help',id,'aria-label="More information"','quiet-help');
const shortDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value||'')?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')):esc(value);
const empty=s=>`<p class="empty">${s}</p>`;
const amount=n=>`<span class="amount ${n<0?'negative':''}">${dollars(n)}</span>`;
const plainInput=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value)=>`<label>${label}<select name="${name}">${options.map(o=>Array.isArray(o)?o:[o,o]).sort((a,b)=>a[0]===''?-1:b[0]===''?1:String(a[1]).localeCompare(String(b[1]),'en',{sensitivity:'base',numeric:true})).map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const check=(label,name,checked)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
function itemRow(key,name,detail,icon,tone,value,options,estimateHelp=false){return `<details class="unified-item" data-section-key="item-${esc(key)}"><summary class="unified-item-summary${icon?'':' without-icon'}">${icon?iconBadge(icon,tone):''}<span class="item-copy"><strong>${esc(name)}</strong><small>${detail}</small></span>${value==null?'':estimateHelp?`<span class="income-estimate"><span class="amount-bubble tone-${tone}">${dollars(value)}</span><button class="income-help" type="button" data-action="incomeHelp">How estimates work</button></span>`:`<span class="amount-bubble tone-${tone}">${dollars(value)}</span>`}<span class="item-chevron" aria-hidden="true">›</span></summary><div class="item-options">${options}</div></details>`;}
const row=(name,detail,actions)=>`<div class="row"><div><strong>${esc(name)}</strong><small>${detail}</small></div><div class="actions">${actions}</div></div>`;
function sectionIcon(title){const rules=[[/forecast/i,'plan','blue'],[/check-in/i,'weekly','lav'],[/allocation|income/i,'income','mint'],[/needs/i,'addNeed','mint'],[/wish/i,'heart','rose'],[/goal/i,'target','lav'],[/sinking/i,'sinking','blue'],[/debt/i,'totalDebt','indigo'],[/payment/i,'payment','indigo'],[/recovery|deleted/i,'health','blue'],[/account|preferences/i,'settings','blue'],[/review|transactions|history/i,'review','blue'],[/bills|renewal/i,'calendar','blue']];const match=rules.find(([pattern])=>pattern.test(title));return match?`<span class="section-icon tone-${match[2]}" aria-hidden="true">${uiIcon(match[1])}</span>`:'';}
const card=(title,body,actions='')=>`<section class="section card"><div class="section-head"><h2>${sectionIcon(title)}${title}</h2>${actions.replace('class="secondary"','class="primary"')}</div>${body}</section>`;
const accounts=(kind='cash')=>S.accounts.filter(a=>kind==='all'||(kind==='debt'?a.kind!=='cash':a.kind===kind)).map(a=>[a.id,a.name]);
const remove=(list,id)=>btn(list==='bills'?'Delete':list==='payments'?'Remove Payment':'Remove','remove',id,`data-list="${list}"`,'danger');

let designModeActive=new URLSearchParams(location.search||'').has('design-preview');
async function api(path,body){if((designModeActive||document.body?.dataset.phoneEditor==='true')&&body)throw Error('Design Mode is preview-only. Close the editor to save budget changes.');const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Budget-HQ':'1'},...(body?{body:JSON.stringify(body)}:{})}),d=await r.json();if(r.status===401){sessionStorage.setItem('budget-route',location.hash);location.replace('/login');throw Error('Please sign in again.');}if(!r.ok)throw Error(d.error||'Request failed.');return d;}
let noticeVersion=0;
function expireNotice(){const node=$('#notice');node.className='';void node.offsetWidth;node.className='success-toast';const version=++noticeVersion;setTimeout(()=>{if(version===noticeVersion)$('#notice').innerHTML='';},5000);}
function notice(s){++noticeVersion;$('#notice').className='error-notice';$('#notice').textContent=s;}
const plaidWarningDismissalKey='budget-hq.plaid-warning-dismissals.v1';
const plaidRefreshWarningKey='budget-hq.plaid-refresh-warning.v1';
let plaidRefreshWarningMemory='';
function plaidWarningText(value){return String(value||'').replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/\s+/g,' ').trim();}
function plaidWarningDismissals(){try{const stored=JSON.parse(localStorage.getItem(plaidWarningDismissalKey)||'{}');return stored&&typeof stored==='object'?stored:{};}catch{return {};}}
function plaidRefreshWarning(){try{return localStorage.getItem(plaidRefreshWarningKey)||plaidRefreshWarningMemory;}catch{return plaidRefreshWarningMemory;}}
function setPlaidRefreshWarning(message){plaidRefreshWarningMemory=message||'';try{if(message)localStorage.setItem(plaidRefreshWarningKey,message);else{localStorage.removeItem(plaidRefreshWarningKey);const dismissed=plaidWarningDismissals();delete dismissed['plaid-refresh'];localStorage.setItem(plaidWarningDismissalKey,JSON.stringify(dismissed));}}catch{}}
function plaidRefreshWarningVisible(){const message=plaidRefreshWarning();return !!message&&plaidWarningDismissals()['plaid-refresh']!==message;}
function warningBox(id,body){if(plaidWarningDismissals()[id]===plaidWarningText(body))return '';return '<div id="warning-'+esc(id)+'" class="warning-note" role="alert">'+body+btn(uiIcon('close'),'dismissWarning',id,'aria-label="Dismiss warning" title="Dismiss warning"','warning-dismiss')+'</div>';}
function dismissPlaidWarning(id){const node=document.getElementById('warning-'+id);if(!node)return;const dismissed=plaidWarningDismissals();dismissed[id]=plaidWarningText(node.textContent);try{localStorage.setItem(plaidWarningDismissalKey,JSON.stringify(dismissed));}catch{}node.remove();}
function successNotice(s){$('#notice').textContent='✓ '+s;expireNotice();}
async function load(){
 const d=await api('budget');activeVersion=d.appVersion||'Unavailable';B=d.book;S=d.summary;
 await render();startLiveUpdates();setTimeout(maybeReviewMissingBill,0);
}
const reviewedThisVisit=new Set();
function maybeReviewMissingBill(){
 if(!B||designModeActive||$('#modal')?.open)return;
 const entry=unmatchedScheduledBills(B,S.asOf).find(e=>!reviewedThisVisit.has(e.key));if(!entry)return;
 reviewedThisVisit.add(entry.key);
 show('Check a Scheduled '+(entry.kind==='debt'?'Payment':'Bill'),'<p>'+esc(entry.name)+' was due '+shortDate(entry.date)+' for '+dollars(entry.amount)+'. No matching posted or pending transaction was found within three days of the date and about 10% of the amount. Bank activity can arrive late.</p><div class="actions">'+btn('Skip This Occurrence','skip',entry.key,'data-date="'+entry.date+'"')+(entry.kind==='debt'?btn('Paid Another Way','payment',entry.id,'data-key="'+entry.key+'"'):btn('Paid Another Way','billPaid',entry.key,'data-date="'+entry.date+'"'))+btn('Remind Me Later','billReviewLater',entry.key)+'</div><p>A choice changes only this occurrence. Nothing is marked skipped or paid automatically.</p>');
}
// Live updates: new app files and budget changes appear without a manual refresh.
// A reload waits while a dialog or Design Mode is open so nothing you are typing is lost.
let liveUpdates=null;
function startLiveUpdates(){
 if(liveUpdates)return;
 liveUpdates=connectLive({
  pageAssets:document.querySelector('meta[name="budget-hq-assets"]')?.getAttribute('content')||'',
  onBudget:()=>refreshBudgetIfIdle(),
  canReload:()=>!designModeActive&&!$('#modal')?.open,
  onWaiting:()=>{if($('#notice')&&!$('#notice').textContent.startsWith('Update ready'))$('#notice').textContent='Update ready — it will load when you close this window.';}
 });
}
async function saveChange(action,data){const before=S,d=await api('write',{revision:B.revision,operationId:requestId(),action,data});B=d.book;S=d.summary;close();await render();$('#notice').innerHTML=`<span>✓ ${esc(changeDescription(before,S,action))}</span>${d.undoId?btn('UNDO','undoNow',d.undoId):''}`;expireNotice();}
async function undoNow(id){const p=await api('preview',{kind:'undo',id}),d=await api('restore',{token:p.token});B=d.book;S=d.summary;close();await render();successNotice('Change Undone');}
function provenance(a){if(a.plaid)return 'Plaid current balance · retrieved '+new Date(a.plaid.retrievedAt).toLocaleString()+' · may be cached'+(a.plaid.liability?' · bank APR/payment details; later months projected':'');return !a.verified?'Unconfirmed imported balance':a.confirmedAt?`Manually confirmed ${a.confirmedAt} · includes recorded activity`:`Starting balance ${a.balanceDate} · includes recorded activity`;}
const originalTabs=[['home','⌂','Home'],['calendar','▣','Calendar'],['plan','▥','Plan'],['debt','●','Debt'],['goals','⚑','Goals'],['surprise','☺','Surprise'],['settings','⚙','Settings']];
function originalNav(){return originalTabs.map(([id,icon,label])=>`<button data-action="navigate" data-id="${id}" class="${page===id?'active':''}"><span class="ico">${uiIcon(id)}</span>${label}</button>`).join('');}
function mobileNav(){return originalTabs.filter(([id])=>!['settings','surprise'].includes(id)).map(([id,icon,label])=>`<button data-action="navigate" data-id="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="ico">${uiIcon(id)}</span>${label}</button>`).join('');}

function kpiTile(label,value,note,action='accounts',id='',color=''){return `<button class="card kpi safe-spend-card ${label==='Current Balance'?'kpi-balance':label.startsWith('Safe to Spend')?'kpi-safe '+(S.cash.safeToSpend<0?'safe-negative':'safe-positive'):label==='Next Payday'?'kpi-payday':label.startsWith('Budget Health')?'kpi-health '+(S.health>=80?'health-good':S.health>=50?'health-fair':'health-low'):''}" data-action="${action}" data-id="${id}">${iconBadge(label==='Current Balance'?'wallet':label.startsWith('Safe to Spend')?(S.cash.safeToSpend<0?'down':'up'):label==='Next Payday'?'calendar':label==='Total Debt'?'debt':label==='Debt Accounts'?'review':label==='Payments / Month'?'calendar':label==='Recorded Payments'?'payment':label==='Current Buffer'?'wallet':label==='Can I Afford This?'?'search':label==='Wish List Savings'?'surprise':label==='Financial Goal Progress'?'target':label==='Next Target'?'calendar':'health',label.startsWith('Safe to Spend')?'mint':label.startsWith('Budget Health')?'lav':'blue')}<span class="kpi-copy"><span class="label">${label}</span><div class="value ${color}">${value}</div><small class="muted">${note}</small></span></button>`;}

function openDialog(title,body,handler=null){$('#modal').dataset.designDialog=title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,80);focusBefore=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=handler?`<form id="edit-form" class="form">${body}<p class="error" id="form-error" role="alert"></p><div class="actions form-actions">${btn('Cancel','close')}<button class="primary" type="submit">Save</button></div></form>`:body;saveHandler=handler;if(!$('#modal').open){if(designModeActive)$('#modal').show();else $('#modal').showModal();}$('#modal-body').scrollTop=0;const submit=$('#modal-body button[type=submit]');if(submit&&handler)submit.textContent=title.startsWith('Skip')?'Skip This Occurrence':title.startsWith('Delete')?title.replace(/\?$/,''):title.startsWith('Remove')?'Remove Record':title==='Record Debt Payment'?'Record Payment':title==='Correct Current Balance'?'Correct Balance':title==='Confirm Account Balance'?'Confirm Balance':title==='Weekly Check-in'?'Finish Check-in':'Save';if(submit&&handler)submit.innerHTML=actionLabel(esc(submit.textContent));restoreDisplay($('#modal-body'),'dialog:'+title);}
function closeDialog(){$('#modal').close();saveHandler=null;focusBefore?.focus();}
function forecastTable(points){return `<div class="scroll"><table><thead><tr><th>Date</th><th>Income</th><th>Bills & debt</th><th>After earmarked savings</th></tr></thead><tbody>${points.map(p=>`<tr><td>${p.date}</td><td>${dollars(p.income)}</td><td class="negative">−${dollars((p.scheduled||0)+(p.reserve||0))}</td><td class="${p.cash<S.cash.bufferTarget?'negative':''}">${dollars(p.cash)}</td></tr>`).join('')}</tbody></table></div>`;}

function readiness(){if(S.ready)return '';const pending=reviewState(B).balances.length,gaps=scheduleGaps(B,S.asOf),id='readiness',accounts=!S.accounts.some(a=>a.kind==='cash')||pending;return '<div id="warning-'+id+'" class="banner" role="alert"><strong>'+(accounts?'Check account balances.':'Complete your schedules.')+'</strong> '+(accounts?'Add and confirm a cash account in Settings → Accounts & Connections.':gaps.bills.length+' bill(s) and '+gaps.debts.length+' debt schedule(s) need review.')+' '+(accounts?btn('Review Accounts','reviewAccounts'):btn('Review Schedules','navigate',gaps.bills.length?'calendar':'debt'))+'</div>';}
function attentionMarkup(){const items=attentionItems(B,S);if(!items.length)return '<section class="section attention-section"><div class="section-head"><h2>Needs Attention</h2></div><div class="attention-empty">Nothing here</div></section>';return '<section class="section attention-section"><div class="section-head"><h2>Needs Attention</h2><span>'+items.length+' things</span></div><div class="grid attention">'+items.map(item=>'<div class="attention-item"><button class="attention-card attention-link" data-attention="'+esc(item.key)+'" data-action="'+esc(item.action)+'" data-id="'+esc(item.id||'')+'">'+iconBadge(...({accounts:['reviewAccounts','blue'],uncategorized:['uncategorized','gray'],records:['review','blue'],checkin:['weekly','lav'],buffer:['buffer','peach'],needs:['needs','gold']}[item.key]||['warning','rose']))+'<b>'+esc(item.title)+'</b><p>'+esc(item.detail)+'</p><span class="attention-go'+(item.key==='uncategorized'?' attention-resolve':'')+'">'+(item.key==='uncategorized'?'Resolve':'Open →')+'</span></button>'+(item.key==='uncategorized'?btn(uiIcon('close'),'dismissAttention',item.key,'aria-label="Dismiss Other transactions warning" title="Dismiss warning"','warning-dismiss'):'')+'</div>').join('')+'</div></section>';}
function reviewAccounts(){const pending=reviewState(B).balances;show('Review Accounts',pending.length?`<p>${pending.length} balance(s) left to confirm. Confirmed accounts disappear from this list.</p>${pending.map(a=>{const current=S.accounts.find(x=>x.id===a.id);return row(a.name,esc(a.institution||a.kind),amount(current.balance)+btn('Confirm Balance','confirmAccount',a.id));}).join('')}`:`<p>All account balances are confirmed.</p>${btn('Done','close')}`);}
function confirmAccount(id){const a=S.accounts.find(a=>a.id===id);if(!a)throw Error('Reload your accounts first.');show('Confirm Account Balance',`<p>${esc(a.name)}</p><p>Enter the current balance shown by your bank or lender. Confirming the same amount still clears this review item.</p>${input('Current Balance','balance',a.balance,'number','step="0.01" required')}`,async d=>{await write('confirmBalance',{...d,id});if(reviewState(B).balances.length)reviewAccounts();});}

function incomeOptions(id){const e=S.nextPaychecks.find(e=>e.id===id);if(!e)return;show(e.name,`<p>${esc(e.date)} · ${dollars(e.amount)} · Expected Income</p><div class="actions">${btn('Received','receive',e.id)}${btn('Edit Income','income',e.id)}</div>`);}

function iconBadgeMarkup(name,tone='blue'){return `<span class="icon-badge tone-${tone}" aria-hidden="true">${uiIcon(name)}</span>`;}
function typeIcon(e){if(e.debtId)return debtIcon(S.accounts.find(a=>a.id===e.debtId));return TYPE_BY_NAME.get(expenseCategory(e))?.icon||'other';}
const debtIcon=a=>a?.icon||((a?.kind==='credit')?'credit':/car|auto/i.test(a?.name||'')?'car':/student/i.test(a?.name||'')?'student':'personalLoan');
const debtIconChoices=debtIconNames.map(name=>[name,name.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase())]);
const checkingAccounts=()=>{const cash=S.accounts.filter(a=>a.active!==false&&a.kind==='cash'),named=cash.filter(a=>/checking/i.test(a.name));return named.length?named:cash.filter(a=>!/regular\s+share/i.test(a.name));};
const savingsAccounts=()=>S.accounts.filter(a=>a.active!==false&&a.kind==='cash'&&/regular\s+share/i.test(a.name));
const cashAccountAmount=items=>Math.round(items.reduce((sum,a)=>sum+((S.cash.balanceDetails||[]).find(d=>d.id===a.id)?.balance??a.balance),0)*100)/100;
function calendarTotals(data,start,end){const predicted=(data.predictedEvents||data.events).filter(e=>e.date>=start&&e.date<=end).reduce((s,e)=>s+e.amount,0),totals=activityTotals(B,S,start,end),actual=Math.round((totals.spending+totals.payments)*100)/100;return {predicted,actual,difference:Math.round((predicted-actual)*100)/100,withheld:totals.withheld};}

// The type used for an expense's colour and icon: the bill's own type when set, otherwise a guess from its name.
function expenseCategory(e){
 const b=B.bills.find(b=>b.id===e.id),name=String(e.name||'').toLowerCase();
 if((!b?.category||['Medical','Other'].includes(b.category))&&/\bvet(?:erinary)?\b|animal hospital/.test(name))return 'Pets';
 if(b?.category)return b.category;
 if(e.debtId)return 'Debt payment';
 for(const [pattern,type] of [[/\binsurance\b/,'Insurance'],[/car|auto|fuel|vehicle/,'Transportation'],[/mint mobile|mobile phone|cell phone|phone|wireless|verizon|at&t|t mobile|tmobile/,'Phone'],[/electric|water|internet|utility|gas/,'Utilities'],[/grocer|market/,'Groceries'],[/restaurant|coffee|pizza|dining/,'Dining out'],[/rent|mortgage/,'Housing'],[/doctor|dental|medical/,'Medical'],[/flight|airfare|hotel|travel/,'Travel'],[/shopping|clothing/,'Shopping'],[/tuition|school|class/,'Education'],[/pet|dog|cat food/,'Pets'],[/salon|barber|haircut/,'Personal care'],[/tax\b|irs/,'Taxes'],[/donation|charity/,'Donations']])if(pattern.test(name))return type;
 return 'Other';
}
let selectedDay='',calendarIncome=[];
function selectedDateLabel(value){const day=Number(value.slice(-2)),suffix=day%100>=11&&day%100<=13?'th':({1:'st',2:'nd',3:'rd'}[day%10]||'th');return new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z'))+suffix;}

async function calendarMonthView(){calendarMonth=location.hash.split('/')[1]||S.asOf.slice(0,7);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(calendarMonth))calendarMonth=S.asOf.slice(0,7);const start=calendarMonth+'-01',date=new Date(start+'T00:00:00Z'),end=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+1,0)).toISOString().slice(0,10),gridStart=add(start,-date.getUTCDay()),gridEnd=add(end,6-new Date(end+'T00:00:00Z').getUTCDay()),data=await api('calendar?start='+gridStart+'&end='+gridEnd+'&revision='+encodeURIComponent(B.revision)+'&asOf='+S.asOf);if(data.budget){B=data.budget.book;S=data.budget.summary;}calendarEvents=data.events.filter(e=>e.date>=start&&e.date<=end);const activeKeys=new Set(calendarEvents.map(e=>e.key));calendarRecordedEvents=(data.predictedEvents||[]).filter(e=>e.date>=start&&e.date<=end&&e.date<S.asOf&&!activeKeys.has(e.key)&&(e.status==='Paid'||B.transactions.some(t=>t.occurrenceKey===e.key)||B.payments.some(p=>p.occurrenceKey===e.key))).map(e=>({...e,readOnly:true}));calendarIncome=data.income.filter(e=>e.date>=start&&e.date<=end);const days=Number(end.slice(-2)),lead=date.getUTCDay(),label=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(date),monthEvents=data.predictedEvents||data.events;return readiness()+`<div class="calendar-page"><div class="grid two-col calendar-estimates">${(()=>{const t=calendarTotals(data,start,end);return card('SCHEDULED THIS MONTH',`${iconBadge('predicted','rose')}<div class="value">${dollars(t.predicted)}</div><small>${label} · bills, debt & one-time items, including paid</small>`)+card('ACTUAL',`${iconBadge('actual','mint')}<div class="value">${dollars(t.actual)}</div><small>Recorded spending & payments${t.withheld?` · ${t.withheld} suspected duplicate records withheld from history`:""}</small>`)+card('DIFFERENCE',`${iconBadge('difference','lav')}<div class="value ${t.difference<0?'negative':''}">${dollars(t.difference)}</div><small>${t.difference<0?'Over':'Under'} predicted spending</small>`);})()}</div><section class="card calendar-card"><div class="calendar-toolbar"><h2>${label}</h2><div class="calendar-controls">${btn('←','month','-1','aria-label="Previous month"')}${btn('Today','month','0')}${btn('→','month','1','aria-label="Next month"')}</div></div><div class="scroll"><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array.from({length:Math.ceil((lead+days)/7)*7},(_,i)=>{const d=add(gridStart,i);return `<div class="day ${d.startsWith(calendarMonth)?'':'adjacent-month'} ${d===S.asOf?'today':''}" data-action="selectDay" data-id="${d}">${btn(String(Number(d.slice(-2))),'selectDay',d,`aria-label="View ${d}"`,'day-number')}<span class="calendar-dots">${calendarEvents.filter(e=>e.date===d).map(e=>`<span class="calendar-event-dot icon-badge tone-${calendarEventTone(e)}" title="${esc(e.name)} · ${expenseCategory(e)} · ${dollars(e.amount)}"></span>`).join('')}${calendarIncome.filter(e=>e.date===d).map(e=>`<span class="calendar-event-dot income" title="${esc(e.name)} · ${dollars(e.amount)}"></span>`).join('')}</span></div>`;}).join('')}</div></div><div id="day-details" class="day-details" aria-live="polite">${dayDetails()}</div></section>`+card(label+' Recurring & One-time Bills','<details class="bill-frequency-group" data-section-key="month-recurring-bills" open><summary>Recurring Expenses</summary>'+calendarMonthBillRows(monthEvents,start,end,'recurring')+'</details><details class="bill-frequency-group" data-section-key="month-one-time-bills"><summary>One-time Bills</summary>'+calendarMonthBillRows(monthEvents,start,end,'once')+'</details>')+scheduledNeedMatches()+'</div>';}
function forecastLowIndexes(points){const out=[];for(let i=0;i<points.length;){let end=i;while(end+1<points.length&&points[end+1].cash===points[i].cash)end++;if((i===0||points[i].cash<points[i-1].cash)&&(end===points.length-1||points[i].cash<points[end+1].cash))out.push(i);i=end+1;}return out;}
function forecastChart(points){if(!points.length)return empty('No forecast available.');const lows=forecastLowIndexes(points),initial=points.reduce((best,p,i)=>p.cash<points[best].cash?i:best,0),w=900,h=290,left=86,right=26,top=22,bottom=40,lo=Math.min(0,S.cash.bufferTarget,...points.map(p=>p.cash)),hi=Math.max(S.cash.bufferTarget,...points.map(p=>p.cash)),pad=Math.max(100,(hi-lo)*.1),min=lo-pad,max=hi+pad,x=i=>left+i*(w-left-right)/Math.max(1,points.length-1),y=v=>top+(max-v)/(max-min)*(h-top-bottom),path=points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${y(p.cash).toFixed(2)}`).join(' '),bufferY=y(S.cash.bufferTarget),step=(w-left-right)/Math.max(1,points.length-1);return `<label class="phone-forecast-picker">Inspect a Forecast Day<select data-forecast-date><option value="">Choose a day…</option>${points.map(p=>`<option value="${p.date}">${shortDate(p.date)} · ${dollars(p.cash)}</option>`).join('')}</select></label><div class="plan-chart"><svg viewBox="0 0 ${w} ${h}" role="group" aria-label="60-day balance forecast with buffer and payday markers"><defs><clipPath id="forecast-below"><rect x="${left}" y="${bufferY}" width="${w-left-right}" height="${h-bottom-bufferY}"/></clipPath></defs>${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return `<line class="forecast-gridline" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${dollars(v)}</text>`;}).join('')}<rect class="forecast-risk-zone" x="${left}" y="${bufferY}" width="${w-left-right}" height="${h-bottom-bufferY}"/><line class="forecast-buffer" x1="${left}" x2="${w-right}" y1="${bufferY}" y2="${bufferY}"/><path class="forecast-balance" d="${path}"/><path class="forecast-shortfall" clip-path="url(#forecast-below)" d="${path}"/>${points.map((p,i)=>`${p.income>0?`<circle class="forecast-payday" cx="${x(i)}" cy="${y(p.cash)}" r="5"/>`:''}${lows.includes(i)?`<circle class="forecast-low-dot" cx="${x(i)}" cy="${y(p.cash)}" r="6"/>`:''}${[0,14,28,42,points.length-1].includes(i)?`<text x="${x(i)}" y="${h-12}" text-anchor="middle">${p.date.slice(5)}</text>`:''}<rect class="forecast-hit" x="${Math.max(left,x(i)-step/2)}" y="${top}" width="${i===0||i===points.length-1?step/2:step}" height="${h-top-bottom}" tabindex="0" role="button" aria-label="${p.date}: ${dollars(p.cash)}. View daily details" data-forecast-index="${i}" data-action="forecastPoint" data-id="${i}"/>`).join('')}</svg></div><p class="muted">Blue: projected balance · Dashed: cash buffer · Green dots: paydays · Red dots: projected low points · Red line: below buffer</p><div id="forecast-readout" class="forecast-readout low-point" aria-live="polite">${forecastReadout(initial)}</div><p class="muted">Hover or focus a day for amounts. Click it to inspect the bills. Includes entered schedules only. Money reserved for wishes, goals and sinking funds (${dollars(S.protectedSavings||0)}) is already deducted once from the forecast.</p>`;}
function forecastReadout(i){const p=S.plan.forecast[i];if(!p)return '';return `<b class="${forecastLowIndexes(S.plan.forecast).includes(Number(i))||p.cash<S.cash.bufferTarget?'readout-low':''}">${selectedDateLabel(p.date)}</b><span>Income ${dollars(p.income)}</span><span>Bills & Debt ${dollars((p.scheduled||0)+(p.reserve||0))}</span><span class="${p.cash<S.cash.bufferTarget?'negative':''}">Balance ${dollars(p.cash)}</span>`;}

function planSections(){return readiness()+card('60-Day Cash Forecast',S.ready?`<p class="plan-reserved-note">Cash in accounts: ${dollars(S.cash.balance)} · Set aside for wishes, goals and sinking funds: −${dollars(S.protectedSavings||0)} · Forecast starting cash: ${dollars(S.cash.balance-(S.protectedSavings||0))}</p>`+`<div class="plan-low"><div><small>Lowest Projected Balance</small><strong class="${S.cash.minimumCash<0?'negative':''}">${dollars(S.cash.minimumCash)}</strong><span>${selectedDateLabel(S.cash.minimumCashDate)}</span></div></div>${forecastGraph(S.plan.forecast)}`:empty('Confirm your balances and schedules to see the forecast.'))+card('Next Paycheck Plan',paycheckPanel());}

function calendarNeeds(){const ordered=B.needs.slice().sort((a,b)=>({High:0,Medium:1,Low:2}[a.urgency]??1)-({High:0,Medium:1,Low:2}[b.urgency]??1));return card('Needs','<p>Suggested dates for your priorities. '+help('needs')+'</p>'+(ordered.map(n=>'<div class="need-direct">'+iconBadge(priorityIcon(n.urgency),priorityTone(n.urgency))+'<div><strong>'+esc(n.name)+'</strong><small>'+esc(needDate(n.cost,n.urgency)?'Suggested: '+shortDate(needDate(n.cost,n.urgency)):'No suggested date yet')+'</small></div><span class="amount-bubble tone-blue">'+dollars(n.cost)+'</span><div class="actions">'+btn('Schedule','scheduleNeed',n.id)+btn('Edit','need',n.id)+trashButton('remove',n.id,'data-list="needs"','Remove Need')+'</div></div>').join('')||empty('No Needs to schedule.')),btn('Add Need','need'));}

function wishCooldownNote(wish){const state=wishPauseState(wish,B,S.asOf,S);return (state.bufferPaused?'<small class="wish-cooldown">Automatically paused: Current Balance is below your '+dollars(S.cash.bufferTarget)+' cash buffer. Resumes when the buffer is restored.</small>':'')+(state.manualPaused?'<small class="wish-cooldown">Manually paused'+(state.until?' until '+selectedDateLabel(state.until):' · no end date')+'</small>':'');}

function transactionRows(items){return items.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${t.date}<br>${esc(t.name)}<small>${t.historical?' · history only':''}${t.paymentId?' · matched payment':''}</small></td><td class="${t.direction==='Outflow'?'negative':'positive'}">${t.direction==='Outflow'?'−':'+'}${dollars(t.amount)}</td><td>${t.adjustment?'Balance correction':`<select aria-label="Category for ${esc(t.name)}" data-category="${t.id}">${[...new Set([t.category,...categories])].sort((a,b)=>a.localeCompare(b,'en',{sensitivity:'base'})).map(c=>`<option ${c===t.category?'selected':''}>${esc(c)}</option>`).join('')}</select>`}</td><td>${!t.adjustment?btn('Edit','transaction',t.id):''}${remove('transactions',t.id)}</td></tr>`).join('')||'<tr><td colspan="4">No transactions recorded.</td></tr>';}
function skippedExpenses(){return Object.entries(B.overrides).filter(([key,value])=>value.status==='Skipped').sort(([a],[b])=>a.split('@')[1].localeCompare(b.split('@')[1])).map(([key,value])=>row(value.name||B.bills.find(b=>b.id===key.split('@')[0])?.name||B.accounts.find(a=>a.id===key.split('@')[0])?.name||B.incomes.find(i=>i.id===key.split('@')[0])?.name||'Scheduled entry',key.split('@')[1],btn('Restore Occurrence','restoreOccurrence',key))).join('')||empty('No skipped occurrences. Bills skipped from Home appear here, including other months.');}

async function renderPage(){const v=++renderVersion;page=location.hash.slice(1).split(/[/?]/)[0]||'home';if(!pages[page])page='home';sessionStorage.setItem('budget-route',location.hash||'#home');$('#title').textContent=page==='home'?'Budget HQ':page==='calendar'?'Bill Calendar':pages[page];$('#navigation').innerHTML=originalNav();if($('#tool-links'))$('#tool-links').innerHTML=originalTools();if($('#month-pill')){const month=Number(S.asOf.slice(5,7))-1;$('#month-pill').className='month-pill month-'+(month+1);$('#month-pill').innerHTML=`<span class="month-art" aria-hidden="true">${monthArt(month)}</span><span>${new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(S.asOf+'T12:00:00Z'))}</span>`;}if($('#subtitle'))$('#subtitle').textContent=({home:'What needs your attention, what is safe, and what comes next.',calendar:'Keep track of what’s due. Stay ahead.',recurring:'Review recurring bills and suggestions.',plan:'Forecast and paycheck plan.',debt:'Payoff strategy and progress.',goals:'Save toward what matters.',transactions:'Your activity, organized in one place.',reports:'Your spending, progress, and bigger picture.',settings:'Keep your budget recoverable and private.',surprise:'',annual:'Renewals and your year in review.',income:'Sources, schedules, and dependable estimates.',insights:'Understand what is changing in your spending.'})[page];document.body?.setAttribute?.('data-page',page);const html=await ({home,calendar,recurring,plan,debt,goals,transactions,settings,surprise,annual,income:incomePage,insights,reports}[page])();if(v===renderVersion){$('#content').innerHTML=(B.sampleMode?'<div class="banner"><strong>Sample budget</strong> · Fictional values for testing. Your real records are separate.</div>':'')+html;if($('#mobile-nav'))$('#mobile-nav').innerHTML=mobileNav();restoreDisplay($('#content'),'page:'+page);if(page==='settings'&&['accounts','accounts-list','income','plaid'].includes(location.hash.split('/')[1]))refreshPlaidPanel();}}
function surprise(){return card('A Little Break',`<img class="original-surprise" src="/public/fallback-meme.svg" alt="Budget HQ’s original offline illustration"><p class="muted">Original offline artwork. The live meme feed is not connected in this independent version.</p>`);}

function safeSpendWindow(){return 'Next 7 Days';}
function explainBasics(id){if(id==='health')return show('What Budget Health Means',`<p>This is a checklist score, not a credit score or a prediction.</p>${S.scoreParts.map(p=>row(p.name,'',`${p.earned}/${p.max}`)).join('')}<p>Confirm balances, schedule bills, protect the buffer, and review history to improve it. Colors: red below 50, amber from 50–79, and green from 80–100.</p>`);if(!S.ready)return show('Finish Checking Your Budget','<p>Confirm cash account balances and complete any missing or invalid bill and debt schedules. These totals appear once required details are in place.</p>');if(id==='forecast')return show('Projected Low Point',`<p>Starts from cash minus earmarked savings. Adds scheduled income and subtracts scheduled bills and debt payments for 60 days. It includes only activity you have entered.</p>${forecastTable(S.plan.forecast)}`);show('Safe to Spend '+safeSpendWindow(),row('Cash balance','Confirmed starting balances plus recorded activity',dollars(S.cash.balance))+row('Money set aside','Wishes + goals + sinking funds',dollars(-S.protectedSavings))+row('Cash buffer','Your protected minimum',dollars(-S.cash.bufferTarget))+`<details open><summary>Bills and debt payments protected through ${shortDate(S.protectionEnd)}</summary>${eventRows(S.protectedBills)}</details>`+row('Safe to spend','Future paychecks are not counted in today’s spendable cash.',dollars(S.cash.safeToSpend))+(S.cash.safeToSpend<0?'<p class="negative">This is a shortfall against bills, your buffer, and earmarked savings.</p>':''));}

function duplicateDialog(key){const g=reviewState(B).duplicates.find(g=>g.key===key);if(!g)throw Error('This group is no longer in Review.');show('Compare Possible Duplicates',`<p>Matching descriptions, dates and amounts can also be legitimate separate purchases. Compare these records before removing one.</p>${g.items.map(t=>row(t.name,`${t.date} · ${dollars(t.amount)} · ${t.historical?'history only':'affects current balance'} · record ${esc(t.id.slice(0,8))}`,remove('transactions',t.id))).join('')}<div class="actions">${btn('These Are Separate Purchases','dismissDuplicate',key)}</div>`);}
function matchExisting(id){const m=reviewState(B).matches.find(m=>m.payment.id===id);if(!m)throw Error('This match is no longer available.');show('Match Recorded Payment',`<p>${esc(m.payment.debtName)} · ${dollars(m.payment.amount)}</p>${select('Which Cash Expense Is This Payment?','transactionId',m.candidates.map(t=>[t.id,`${t.date} · ${t.name} · ${dollars(t.amount)}`]),'')}<p>Matching keeps the cash expense and removes the payment’s second cash deduction. Principal is not reduced again. You can Undo the match.</p>`,d=>write('matchPayment',{...d,id}));}

function bindConditionalForm(kind){const f=$('#edit-form');if(!f)return;
 const toggle=(el,visible)=>{if(!el)return;el.hidden=!visible;for(const control of el.querySelectorAll('input,select,textarea'))control.disabled=!visible;};
 const label=(name,visible)=>toggle(f.elements[name]?.closest('label'),visible);
 const update=()=>{
  if(kind==='trip'){for(const el of f.querySelectorAll('[data-cost-field]'))toggle(el,tripFieldVisible(el.dataset.costField,f.elements.mode.value,f.elements.rental.checked));label('weeklySaving',f.elements.savingsMode.value==='Choose my own');label('nights',f.elements.dateMode.value==='nights');label('end',f.elements.dateMode.value==='dates');const suggestion=f.querySelector('[data-action="suggestTrip"]');if(suggestion)suggestion.hidden=f.elements.dateMode.value!=='nights';}
  if(kind==='account'){label('limit',f.elements.kind.value==='credit');label('original',['loan','personal'].includes(f.elements.kind.value));label('icon',f.elements.kind.value!=='cash');if(f.elements.debtCategory){label('debtCategory',f.elements.kind.value!=='cash');if(f.elements.kind.value==='credit')f.elements.debtCategory.value='credit';else if(f.elements.kind.value==='personal')f.elements.debtCategory.value='personal';else if(f.elements.debtCategory.value==='credit')f.elements.debtCategory.value='other';}const terms=f.querySelector('.account-terms>summary');if(terms)terms.textContent=f.elements.kind.value==='credit'?'Card Details':'Loan Details';}
  if(kind==='need')toggle(f.querySelector('[data-custom-date]'),f.elements.dateMode.value==='custom');
  if(kind==='goal')label('weekly',f.elements.style.value==='Custom');
 };f.addEventListener('change',update);update();
}
function accountForm(id,kind='cash'){
 const a=B.accounts.find(a=>a.id===id)||{debtType:kind==='personal'?'personal':'',kind:kind==='personal'?'loan':page==='debt'&&kind==='cash'?'loan':kind,openingBalance:0,balanceDate:S.asOf,frequency:'Monthly'};
 const debt=a.kind!=='cash',title=id?(debt?'Edit Debt Account':'Edit Account'):(debt?'Add Debt Account':'Add Account');
 const basics=`<div class="fields">${input('Account Name','name',a.name,'text','required')}${input(debt?'Lender or Person Owed':'Bank / Lender','institution',a.institution)}${select(debt?'Debt Type':'Type','kind',[...(debt?[]:[['cash','Checking / savings / cash']]),['credit','Credit card'],['loan','Loan'],['personal','Personal debt']],a.debtType==='personal'?'personal':a.kind)}${debt&&page==='debt'?select('Debt Category','debtCategory',[['credit','Credit Card'],['student','Student Loan'],['car','Car Loan'],['personal','Personal Debt'],['other','Other Loan']],a.kind==='credit'?'credit':a.debtCategory|| (a.debtType==='personal'?'personal':/student/i.test(a.name||'')?'student':/car|auto|forester/i.test(a.name||'')?'car':'personal')):''}${debt?select('Icon','icon',debtIconChoices,debtIcon(a)):''}</div>`;
 const balance=id?`<section class="account-balance-details"><h3>Current Balance</h3>${input('Correct Current Balance','currentBalance',S.accounts.find(v=>v.id===id).balance,'number','step="0.01" required')}<p>Changing this records a balance correction without rewriting payments.</p></section>`:`<div class="fields account-starting-fields">${input('Starting Balance','openingBalance',a.openingBalance,'number','step="0.01" required')}${input('Balance as of','balanceDate',a.balanceDate,'date',`max="${S.asOf}" required`)}</div>`;
 const terms=debt?`<div class="fields account-payment-fields">${input('Scheduled Payment','payment',a.payment||0,'number','step="0.01" min="0"')}${input('Next Due Date','dueDate',a.dueDate,'date')}${select('Frequency','frequency',freq,a.frequency)}</div><details class="account-terms"><summary>${a.kind==='credit'?'Card Details':'Loan Details'}</summary><div class="fields">${input('APR (%)','apr',a.apr||0,'number','step="0.01" min="0" max="100"')}${input('Credit Limit','limit',a.limit||0,'number','step="0.01" min="0"')}${input('Original Loan Amount','original',a.original||0,'number','step="0.01" min="0"')}</div></details>`:'';
 const history=id?`<details class="account-history"><summary>Starting Details</summary><p>Opening balance ${dollars(a.openingBalance)} on ${shortDate(a.balanceDate)}. Recorded activity is preserved.</p></details>`:'';
 show(title,basics+(id?'':balance)+terms+(id?balance+history:''),d=>write(id?'editAccount':'account',{...a,...d,id,kind:d.kind==='personal'?'loan':d.kind,debtType:d.kind==='personal'?'personal':'',debtCategory:d.kind==='credit'?'credit':d.kind==='personal'?'personal':d.debtCategory||a.debtCategory,currentBalance:d.currentBalance??S.accounts.find(v=>v.id===id)?.balance}));
 bindConditionalForm('account');const f=$('#edit-form'),requireDue=()=>{if(f.elements.dueDate)f.elements.dueDate.required=f.elements.kind.value!=='cash'&&Number(f.elements.payment.value)>0;};f.addEventListener('input',requireDue);f.addEventListener('change',requireDue);requireDue();
 const submit=f.querySelector('button[type="submit"]');if(submit)submit.textContent=id?'Save Changes':'Add Account';
}

function editTransactionForm(id){const t=B.transactions.find(t=>t.id===id)||{date:S.asOf,direction:'Outflow',category:'Other'};show('Record a Transaction',`<div class="fields">${input('Description','name',t.name,'text','required')}${input('Amount','amount',t.amount,'number','min="0.01" step="0.01" required')}${select('Account','accountId',accounts('all'),t.accountId)}${select('Direction','direction',['Outflow','Inflow'],t.direction)}${input('Date','date',t.date,'date',`required max="${S.asOf}"`)}${select('Category','category',[...new Set([t.category,...categories])],t.category)}</div><details><summary>Transfer or Historical Entry</summary>${select('Transfer Destination (Cash Accounts Only)','toAccountId',[['','Not a transfer'],...accounts()],t.toAccountId)}<p>Choose Outflow for transfers. Both sides are recorded together, once.</p>${check('Historical Record: Already Included in the Starting Balance','historical',t.historical)}</details><p>For a debt payment, use Record payment on Debt so both principal and cash are handled together.</p>`,d=>write('transaction',{...d,id}));}
function spendingPayload(d){
 if(d.entryType==='transfer')return {action:'transaction',data:{...d,direction:'Outflow',category:'Transfer',toAccountId:d.toAccountId}};
 if(d.entryType!=='debt')return {action:'transaction',data:d};
 if(!d.debtId)throw Error('Choose the debt to apply this spending to.');
 const candidate=t=>!t.historical&&!t.adjustment&&!t.paymentId&&!t.toAccountId&&t.direction==='Outflow'&&t.accountId===d.accountId&&Number(t.amount)===Number(d.amount)&&Math.abs(Date.parse(t.date)-Date.parse(d.date))<=5*86400000;
 if(!d.transactionId&&d.separatePayment!==true&&(B.transactions.some(candidate)||B.payments.some(p=>p.debtId===d.debtId&&Number(p.amount)===Number(d.amount)&&Math.abs(Date.parse(p.date)-Date.parse(d.date))<=5*86400000)))throw Error('A possible matching payment already exists. Choose the existing cash outflow below, or confirm this is a different payment.');
 return {action:'payment',data:{debtId:d.debtId,amount:d.amount,principal:d.principal,date:d.date,fundingId:d.accountId,transactionId:d.transactionId||'',occurrenceKey:d.occurrenceKey||''}};
}
function transactionForm(id){if(id)return editTransactionForm(id);return spendingForm();}
function paymentForm(id,key=''){const debt=S.accounts.find(a=>a.kind!=='cash'&&a.id===id)||S.accounts.find(a=>a.kind!=='cash');if(!debt)return show('Add a Debt Account First','<p>Create a debt account before recording a payment.</p>');return spendingForm(debt.id,key);}
function spendingForm(debtId='',key=''){
 const debt=S.accounts.find(a=>a.id===debtId&&a.kind!=='cash'),debtMode=!!debt,cashAccounts=accounts('cash');
 const existing=B.transactions.filter(t=>!t.historical&&!t.adjustment&&!t.paymentId&&!t.toAccountId&&t.direction==='Outflow'&&S.accounts.some(a=>a.id===t.accountId&&a.kind==='cash'));
 show('Record Transaction',`<div class="fields"><div class="wide">${select('Transaction Type','entryType',[['spending','Regular transaction'],['transfer','Transfer between my accounts'],['debt','Debt payment']],debtMode?'debt':'spending')}</div>${input('Amount','amount',debt?Math.min(debt.payment||0,Math.max(0,debt.balance)):'','number','min="0.01" step="0.01" required')}${input('Date','date',S.asOf,'date',`required max="${S.asOf}"`)}${select('Account','accountId',[...cashAccounts,...accounts('credit')],cashAccounts[0]?.[0]||accounts('credit')[0]?.[0]||'')}</div><fieldset data-spending-regular class="fields">${select('Money Movement','direction',[['Outflow','Money out (spending)'],['Inflow','Money in (deposit, refund, income)']],'Outflow')}${input('Description','name','','text','required')}${select('Category','category',categories.filter(c=>c!=='Debt payment'),'Other')}<details class="wide"><summary>Historical Entry (Advanced)</summary>${check('Already Included in Starting Balance','historical',false)}<p>Keep past activity in your records without changing your balance again. Leave this unchecked for a new transaction.</p></details></fieldset><fieldset data-spending-transfer class="fields"><div class="wide">${select('Transfer To','toAccountId',cashAccounts,cashAccounts.find(a=>a[0]!==cashAccounts[0]?.[0])?.[0]||'')}</div>${input('Description','name','Transfer','text','required')}<p class="wide">Money moves between two cash accounts. Your combined cash balance stays the same.</p><details class="wide"><summary>Historical Entry (Advanced)</summary>${check('Already Included in Starting Balance','historical',false)}<p>Use only when both account balances already include this transfer.</p></details></fieldset><fieldset data-spending-debt class="fields"><div class="wide">${select('Apply to Existing Debt','debtId',accounts('debt'),debtId)}</div>${input('Amount Applied to Principal','principal','','number','min="0" step="0.01" required')}${select('Scheduled Occurrence Paid','occurrenceKey',[['','Extra / unscheduled payment'],...S.upcoming.filter(e=>e.debtId===debtId).map(e=>[e.key,`${e.name} · ${e.date}`])],key||S.upcoming.find(e=>e.debtId===debtId)?.key||'')}<p class="wide">Principal reduces the debt balance. The rest of the payment is interest or fees. Cash is deducted once.</p><details class="wide"><summary>Match an Existing Bank or Cash Entry</summary>${select('Existing Cash Outflow','transactionId',[['','Record a new payment'],...existing.map(t=>[t.id,`${t.date} · ${t.name} · ${dollars(t.amount)}`])],'')}<p>Matching uses that entry instead of deducting cash again. Already-linked entries cannot be used twice.</p>${check('This Is a Different Payment From Any Similar Recorded Entry','separatePayment',false)}</details></fieldset>`,d=>{const p=spendingPayload(d);return write(p.action,p.data);});
 const f=$('#edit-form');let previousDebt=debtId;
 const update=()=>{const type=f.elements.entryType.value,isDebt=type==='debt',isTransfer=type==='transfer';for(const [selector,on]of [['[data-spending-regular]',type==='spending'],['[data-spending-transfer]',isTransfer],['[data-spending-debt]',isDebt]]){const group=f.querySelector(selector);if(group){group.hidden=!on;group.disabled=!on;}}
  const account=f.elements.accountId;if(isTransfer||isDebt){for(const option of account.options||[])option.disabled=!cashAccounts.some(a=>a[0]===option.value);if(!cashAccounts.some(a=>a[0]===account.value))account.value=cashAccounts[0]?.[0]||'';}else for(const option of account.options||[])option.disabled=false;
  const destination=f.elements.toAccountId;if(isTransfer){for(const option of destination.options||[])option.disabled=option.value===account.value;if(destination.value===account.value||!destination.value)destination.value=cashAccounts.find(a=>a[0]!==account.value)?.[0]||'';}
  const submit=f.querySelector('button[type=submit]');if(submit)submit.textContent=isDebt?'Record Payment':isTransfer?'Record Transfer':'Record Transaction';
  const current=f.elements.debtId.value;if(current!==previousDebt){previousDebt=current;f.elements.occurrenceKey.innerHTML='<option value="">Extra / unscheduled payment</option>'+S.upcoming.filter(e=>e.debtId===current).map(e=>`<option value="${esc(e.key)}">${esc(e.name)} · ${e.date}</option>`).join('');}
 };
 f.addEventListener('change',e=>{update();if(e.target.name==='transactionId'&&e.target.value){const t=existing.find(t=>t.id===e.target.value);if(t){f.elements.accountId.value=t.accountId;f.elements.amount.value=t.amount;f.elements.date.value=t.date;}}});update();
}

function billForm(id,kind='Fixed'){const b=B.bills.find(x=>x.id===id)||{kind,date:S.asOf,frequency:kind==='Planned'?'One-time':'Monthly'};show(id?(b.frequency==='One-time'?'Edit One-time Expense':'Edit Recurring Bill'):'Add Expense',`<div class="fields">${input('Name','name',b.name,'text','required')}${input('Amount','amount',b.amount,'number','step="0.01" min="0" required')}${input('Due Date','date',b.date,'date','required')}${select('Recurrence','frequency',freq,b.frequency)}${select('Category','category',EXPENSE_CATEGORIES,b.category||expenseCategory(b))}</div><p>Editing changes the series. Skip from the calendar to change just one occurrence.</p>`,d=>write('bill',{...d,id,kind:d.frequency==='One-time'?'Planned':'Fixed'}));}
function eventDialog(key){const e=[...S.upcoming,...calendarEvents].find(x=>x.key===key);if(!e)throw Error('Reload the calendar to find this bill.');show(e.name,`<p>${e.date} · ${dollars(e.amount)} · ${esc(e.type)}</p><div class="actions">${btn('Skip This Occurrence','skip',key,`data-date="${e.date}"`)}${e.debtId?btn('Record Payment','payment',e.debtId,`data-key="${esc(key)}"`):btn('Mark Paid','billPaid',key,`data-date="${e.date}"`)}${btn('Edit Series',e.debtId?'account':'bill',e.id)}</div><p>Skipping removes this occurrence from upcoming bills, Safe to Spend, and the projected low point. Later occurrences remain scheduled. You still owe any unpaid debt.</p>`);}
function suggestedDate(cost){if(!S.ready)return '';return S.plan.forecast.find((p,i)=>S.plan.forecast.slice(i).every(x=>x.cash-Number(cost)>=S.cash.bufferTarget))?.date||'';}
function needDate(cost,priority){if(!S.ready||!Number.isFinite(Number(cost))||Number(cost)<=0)return '';const horizon={High:30,Medium:90,Low:180}[priority]||90,points=(S.needForecast||S.plan.forecast).slice(0,horizon);return points.find((p,i)=>points.slice(i).every(x=>x.cash-Number(cost)>=S.cash.bufferTarget))?.date||'';}
function updateNeedDate(){const f=$('#edit-form'),entered=f.elements.cost.value!==''&&Number(f.elements.cost.value)>0,date=entered?needDate(f.elements.cost.value,f.elements.urgency.value):null,days={High:30,Medium:90,Low:180}[f.elements.urgency.value]||90;$('#need-suggestion').className=entered&&!date?'no-date negative':'';if(!entered){$('#need-suggestion').textContent='Enter a cost to find a suggested date.';return;}$('#need-suggestion').textContent=`Suggested date: ${date||'no suitable date available'} · searching ${days} days. Based on entered schedules; longer-range dates are projections.`;}

function wishPriorityChoices(selected='Normal'){return '<fieldset class="priority-options"><legend>Priority</legend>'+['High','Normal','Low'].map(p=>{const tone=p==='Normal'?'Medium':p;return '<label class="priority-choice"><input type="radio" name="priority" value="'+p+'" '+(selected===p?'checked':'')+'>'+iconBadge(priorityIcon(tone),priorityTone(tone))+'<span>'+p+'</span></label>';}).join('')+'</fieldset>';}
function targetForm(id,kind='wish'){const list={wish:'wishes',goal:'goals',sinking:'sinking'}[kind],g=B[list].find(x=>x.id===id)||{saved:0,style:'Automatic',weekly:0};const pauseState=kind==='wish'?wishPauseState(g,B,S.asOf):{paused:effectiveSavingsStyle(g,S.asOf)==='Pause',until:g.pauseUntil||''},currentStyle=pauseState.paused?(g.resumeStyle||(g.style==='Custom'?'Custom':'Automatic')):effectiveSavingsStyle(g,S.asOf);show(kind==='wish'?'Wish Details':kind==='goal'?'Financial Goal':'Sinking Fund',`<div class="fields${kind==='wish'?' wish-fields':''}">${input('Name','name',g.name,'text','required')}${input('Target Cost','cost',g.cost,'number','step="0.01" min="0" required')}${input('Already Set Aside','saved',g.saved,'number','step="0.01" min="0"')}${input('Target Date (Optional)','date',g.date,'date')}</div><details class="wish-section"><summary>Savings Plan</summary>${select('Weekly Savings','style',['Automatic','Custom'],currentStyle)}${input('Custom Weekly Amount','weekly',g.weekly,'number','min="0" step="0.01"')}<p>Suggestions share the selected allocations from your next paycheck across automatic targets. They are plans; money moves only when you update “Already set aside”.</p></details>${kind==='sinking'?'':`<details class="wish-section"><summary>Link & Photo</summary>${input('Website Link','link',g.link,'url')}<p id="photo-lookup" role="status">Paste a purchase link to look for a product photo automatically.</p>${input('Photo URL (Direct HTTPS Image Link)','imageUrl',g.image?.startsWith('https://')?g.image:'','url')}<p>Use a direct image URL or upload a file below. An uploaded file takes priority. Product-page links go in Website link.</p>${input('Your Photo','photoFile','','file','accept="image/*"')}${g.image?'<p>Current photo saved.</p>'+check('Remove Current Photo','clearPhoto',false):''}</details>`}<p>Already set aside is part of your cash balance, reserved for this target. Do not also subtract it as an expense.</p>`,async d=>{const photo=await readPhoto($('#edit-form').elements.photoFile?.files?.[0]);if(!photo&&!d.clearPhoto&&!d.imageUrl&&d.link){try{d.imageUrl=(await api('product-photo',{url:d.link})).image||'';}catch{}}await write(kind,{...d,...(pauseState.paused?{style:'Pause',pauseUntil:pauseState.until,resumeStyle:d.style}:{}),id,image:kind==='sinking'?(g.image||''):d.clearPhoto?'':photo||(d.imageUrl||'').trim()||(g.image?.startsWith('https://')?'':g.image||'')});});bindConditionalForm('goal');const form=$('#edit-form');form.elements.link?.addEventListener('change',async()=>{const url=form.elements.link.value;if(!url)return;$('#photo-lookup').textContent='Looking for a product photo…';try{const result=await api('product-photo',{url});if(form!==$('#edit-form')||form.elements.link.value!==url)return;if(result.image&&!form.elements.imageUrl.value)form.elements.imageUrl.value=result.image;$('#photo-lookup').textContent=result.image?'Product photo found. You can replace it below.':'No photo found. Use a photo URL or upload a file.';}catch{if(form===$('#edit-form'))$('#photo-lookup').textContent='This site could not provide a photo. Use a photo URL or upload a file.';}});}
async function readPhoto(file){if(!file)return '';if(file.size>15000000)throw Error('Choose a photo smaller than 15 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,700/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.8,value=canvas.toDataURL('image/jpeg',quality);while(value.length>175000&&quality>.15){quality-=.1;value=canvas.toDataURL('image/jpeg',quality);}if(value.length>180000)throw Error('This photo is too detailed. Choose a smaller photo.');return value;}

function afford(){if(!S.ready)return explain('forecast');show('Can I Afford This?',`<p>Check one purchase against your bills, reserved savings and cash buffer in the loaded 60-day forecast.</p><div class="fields">${input('Purchase Amount','purchase','','number','min="0.01" step="0.01" required')}${input('Buy on','date',S.asOf,'date',`min="${S.asOf}" max="${S.plan.forecast.at(-1).date}" required`)}</div>`,d=>{const cost=Number(d.purchase);if(!Number.isFinite(cost)||cost<=0)throw Error('Enter a purchase amount greater than zero.');const r=calculateScenario(S.plan.forecast,{purchase:cost,date:d.date,start:S.asOf,buffer:S.cash.bufferTarget}),earliest=suggestedDate(cost);show('Purchase Check',`<div class="result"><h3>${r.belowBuffer?'This would dip below your buffer':'Fits your current forecast'}</h3><p>Projected low point</p><strong>${dollars(r.minimum.cash)}</strong><p>On ${r.minimum.date}</p><p>${r.belowBuffer?`${r.belowBuffer} days below your buffer · largest gap ${dollars(r.shortfall)}`:'Your buffer stays protected throughout the forecast.'}</p><p>Earliest date that fits: <b>${earliest||'None in the loaded forecast'}</b></p></div><p>Based on recorded plans for 60 days. This check has not saved a purchase or changed your budget.</p><div class="actions form-actions">${btn('Check Another Purchase','afford')}${btn('Done','close')}</div>`);});const submit=$('#modal-body button[type=submit]');if(submit)submit.textContent='Check purchase';}
const tripNumbers=['flightFare','baggage','airportTransport','miles','mpg','fuelPrice','tolls','parking','rentalDays','rentalRate','rentalFees','rentalFuel','hotelRate','hotelTax','hotelFees','foodDaily','activities','other','contingency','saved','weeklySaving','upfront'];
const tripLabels={flightFare:'Round-trip flight / traveler',baggage:'Baggage / traveler',airportTransport:'Airport transport total',miles:'Round-trip miles',mpg:'Miles per gallon',fuelPrice:'Fuel / gallon',tolls:'Tolls total',parking:'Parking total',rentalDays:'Rental days',rentalRate:'Rental / day',rentalFees:'Rental fees',rentalFuel:'Rental fuel',hotelRate:'Hotel / night / room',hotelTax:'Hotel tax (%)',hotelFees:'Hotel fees total',foodDaily:'Food / day / traveler',activities:'Activities total',other:'Other costs',contingency:'Contingency (%)',saved:'Trip savings already in cash',weeklySaving:'Your weekly savings',upfront:'Payment required upfront'};
function tripForm(id){const old=B.trips.find(t=>t.id===id),t=old||{name:'',origin:'',destination:'',start:add(S.asOf,7),end:add(S.asOf,10),bookingDate:S.asOf,travelers:1,rooms:1,mode:'Fly',rental:false,savingsMode:'Automatic',...Object.fromEntries(tripNumbers.map(k=>[k,0])),mpg:25};show('Plan a Trip',`<div class="fields">${input('Trip Name','name',t.name,'text','required')}${input('Destination','destination',t.destination,'text','required')}${input('Departure City','origin',t.origin,'text','required')}${select('Travel by','mode',['Fly','Drive'],t.mode)}${select('Date Planning','dateMode',[['dates','Enter dates'],['nights','Enter nights & suggest dates']],'dates')}${input('Number of Nights','nights',Math.round((Date.parse(t.end)-Date.parse(t.start))/86400000),'number','min="1" max="90"')}${input('Departure','start',t.start,'date','required')}${input('Return','end',t.end,'date','required')}${input('Travelers','travelers',t.travelers,'number','min="1" max="30" required')}${input('Hotel Rooms','rooms',t.rooms,'number','min="1" max="30" required')}</div>${check('Include a Rental Car','rental',t.rental)}<div class="actions">${btn('Generate Cost Estimates','estimateTrip')}${btn('Suggest Dates','suggestTrip')}</div><p id="trip-note">Estimates are planning allowances, not live prices or destination-specific quotes. Generate a starting budget, then adjust known prices.</p><details><summary>Travel, Hotel & Daily Costs</summary><div class="trip-costs">${tripNumbers.filter(k=>!['saved','weeklySaving','upfront'].includes(k)).map(k=>`<div data-cost-field="${k}">${input(tripLabels[k],k,t[k],'number','min="0" step="0.01" required')}</div>`).join('')}</div></details><details open><summary>Savings & Payment Timing</summary><div class="fields">${input('Upfront Payment Date','bookingDate',t.bookingDate,'date','required')}${input(tripLabels.upfront,'upfront',t.upfront,'number','min="0" step="0.01"')}${input(tripLabels.saved,'saved',t.saved,'number','min="0" step="0.01"')}${select('Weekly Amount','savingsMode',['Automatic','Choose my own'],t.savingsMode)}${input(tripLabels.weeklySaving,'weeklySaving',t.weeklySaving,'number','min="0" step="0.01"')}</div><p>Trip savings here describe money still inside cash; they are not added to the forecast. If already earmarked in a goal, do not enter it again here.</p></details><details><summary>Your Photo</summary>${input('Choose a Photo','photoFile','','file','accept="image/*"')}${old?.photo?check('Remove Current Photo','clearPhoto',false):''}</details>`,async d=>{if(d.dateMode==='nights')d.end=add(d.start,Number(d.nights));if(tripCost(d).total===0)throw Error('Generate an estimate or enter your known costs before saving the trip.');const photo=await readPhoto($('#edit-form').elements.photoFile.files[0]);return write('trip',{...d,id,photo:photo||(d.clearPhoto?'':old?.photo||'')});});bindConditionalForm('trip');}
function formData(form){const d=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('input[type=checkbox]'))d[el.name]=el.checked;for(const el of form.querySelectorAll('[name]:disabled'))d[el.name]=el.type==='number'?(Number.isFinite(Number(el.value))&&Number(el.value)>=0?el.value:'0'):el.value;delete d.photoFile;return d;}
function tripEstimate(){const f=$('#edit-form'),d=formData(f);if(d.dateMode==='nights'){d.end=add(d.start,Number(d.nights));f.elements.end.value=d.end;}const result=starterTripEstimate(d);for(const [k,v]of Object.entries(result.values))f.elements[k].value=v;$('#trip-note').textContent=result.note;}
function tripSuggestions(){if(!S.ready)throw Error('Confirm your starting budget before asking for affordable dates.');const f=$('#edit-form'),d=formData(f);if(Number(d.hotelRate)===0)tripEstimate();const updated=formData(f),options=suggestTripDates(updated,Number(d.nights),S);if(!options.length){$('#trip-note').textContent='No dates fit within your confirmed 60-day forecast. Choose dates manually or reduce the estimate.';return;}$('#trip-note').innerHTML='Dates that fit your loaded forecast: '+options.map(o=>btn(`${o.selected.start} – ${o.selected.end}`,'chooseTripDate',o.selected.start,`data-end="${o.selected.end}"`)).join('');}
function tripResult(id){const t=B.trips.find(t=>t.id===id),cost=tripCost(t),r=S.ready?evaluateTrip(t,S):null;show(t.name,`${t.photo?`<img class="photo" src="${t.photo}" alt="Your trip photo">`:''}<p>${esc(t.destination)} · ${shortDate(t.start)} – ${shortDate(t.end)}</p><div class="result"><strong>${dollars(cost.total)}</strong>Estimated total · ${cost.nights} nights</div><details open><summary>Cost Breakdown</summary>${cost.lines.map(x=>row(x.label,esc(x.detail),dollars(x.amount))).join('')}</details>${r?`<h3>${esc(r.selected.status)}</h3><p>Weekly suggestion: ${dollars(r.weeklySaving)}. Automatic planning protects your buffer within the loaded forecast; it does not save money automatically.</p><p>Selected travel is ${r.selected.status==='Outside forecast'?'outside the 60-day forecast; affordability cannot be confirmed.':'tested against your entered income and bills.'}</p><p>Earliest date within the forecast: ${r.earliest?.start||'none found'}.</p>`:'<p>Confirm your starting budget to calculate affordability and automatic weekly savings.</p>'}`);}
async function historyDialog(){const d=await api('history'),label=id=>{if(/^backup-\d{4}-\d{2}-\d{2}$/.test(id))return 'Automatic backup · '+shortDate(id.slice(7));if(/^backup-\d{13}-/.test(id))return 'Manual backup · '+new Date(Number(id.split('-')[1])).toLocaleString();return id.replace(/^backup-/, 'Backup · ');};show('Backups & Restore',`<p>Review saved changes and automatic backups. Restoring replaces the current budget after a preview; a backup of today’s budget is saved first.</p><h3>Recent Changes</h3>${d.history.map((h,i)=>row(h.action,new Date(h.date).toLocaleString(),i===0?btn('Preview Undo','preview',h.id,'data-kind="undo"'):'')).join('')||empty('No recent changes.')}<h3>Automatic Backups</h3>${d.backups.map(id=>row(label(id),'',btn('Preview Restore','preview',id,'data-kind="backup"'))).join('')||empty('No saved backups yet.')}`);}

async function reviewImports(){show('Review Imported History',`<p>These candidate records never change your current balances. Check names, amounts, pending entries and transfers before accepting them into year review.</p><div class="actions">${btn('Accept Checked','acceptHistory')}${btn('Discard Checked','discardHistory')}</div><label class="check"><input type="checkbox" id="select-imports"> Select all shown</label><div class="scroll"><table>${B.reviewTransactions.map(t=>`<tr><td><input aria-label="Select ${esc(t.name)}" type="checkbox" data-import="${t.id}"></td><td>${t.date}<br>${esc(t.name)}${t.pending?' · PENDING':''}</td><td>${dollars(t.amount)}</td><td>${t.direction}</td></tr>`).join('')}</table></div>`);$('#select-imports').onchange=e=>document.querySelectorAll('[data-import]').forEach(c=>c.checked=e.target.checked);}
document.addEventListener('submit',async e=>{if(e.target.id!=='edit-form')return;e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await saveHandler(formData(e.target));}catch(err){if($('#form-error'))$('#form-error').textContent=err.message;else notice(err.message);}finally{button.disabled=false;}});
let draggedTarget=null;
document.addEventListener('dragstart',e=>{const handle=e.target.closest?.('[data-target-drag]');if(!handle)return;const card=handle.closest('[data-target-card]');if(!card)return;draggedTarget=card; e.dataTransfer?.setData('text/plain',card.dataset.targetId);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';card.classList.add('target-dragging');});
document.addEventListener('dragend',()=>{draggedTarget?.classList.remove('target-dragging');draggedTarget=null;document.querySelectorAll('.target-drop-hint').forEach(el=>el.classList.remove('target-drop-hint'));});
document.addEventListener('dragover',e=>{const card=e.target.closest?.('[data-target-card]');if(!draggedTarget||!card||card.dataset.targetList!==draggedTarget.dataset.targetList)return;e.preventDefault();document.querySelectorAll('.target-drop-hint').forEach(el=>el.classList.remove('target-drop-hint'));card.classList.add('target-drop-hint');});
document.addEventListener('drop',async e=>{const card=e.target.closest?.('[data-target-card]');if(!draggedTarget||!card||card.dataset.targetList!==draggedTarget.dataset.targetList)return;e.preventDefault();const source=draggedTarget;source.classList.remove('target-dragging');draggedTarget=null;document.querySelectorAll('.target-drop-hint').forEach(el=>el.classList.remove('target-drop-hint'));if(source===card)return;const list=card.dataset.targetList,ids=B[list].map(x=>x.id),from=ids.indexOf(source.dataset.targetId),to=ids.indexOf(card.dataset.targetId);if(from<0||to<0)return;ids.splice(to,0,...ids.splice(from,1));try{await write('reorderTargets',{list,ids});}catch(err){notice(err.message);await load();}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();const {action,id,kind,key,date,list}=el.dataset;try{
 if(await advancedClick(action,id,list))return;
 if(action==='dismissAttention')return await write('dismissAttention',{key:id});
 if(action==='reviewAccounts')return reviewAccounts();if(action==='confirmAccount')return confirmAccount(id);
 if(action==='help')return show('How This Works',`<p>${esc(helpText[id]||'')}</p>`);if(action==='wishCooldown')return wishCooldown(id);if(action==='forecastPoint')return inspectPlanDay(S.plan.forecast[Number(id)]?.date);if(action==='planDay')return inspectPlanDay(id);if(action==='close')return close();if(action==='undoNow')return await undoNow(id);if(action==='more')return show('Tools',`<div class="tool-links">${btn('Settings','navigate','settings')}${originalTools()}${btn('Add Income','income')}${btn(`${uiIcon('spend')} Record Transaction`,'transaction')}${btn('Weekly Check-in','checkin')}</div>`);if(action==='decisionHistory')return show('Decisions & Wins',B.decisions.map(d=>row(d.name,esc(d.notes),d.date)).join('')+btn('Add a Note','decision'));if(action==='checkin')return checkin();if(action==='matchExisting')return matchExisting(id);if(action==='duplicate')return duplicateDialog(id);if(action==='dismissDuplicate')return await write('dismissDuplicate',{key:id});if(action==='navigate'){close();location.hash=id;return;}if(action==='reload')return await refreshBankConnection();if(action==='accounts')return accountsDialog();if(action==='account')return accountForm(id,kind);if(action==='reconcile'){const a=S.accounts.find(a=>a.id===id);return show('Correct Current Balance',`<p>${esc(a.name)} currently shows ${dollars(a.balance)}. Enter the current balance from your bank or lender. The difference is saved as a balance correction, not income or spending.</p>${input('Correct Balance','balance',a.balance,'number','step="0.01" required')}`,d=>write('reconcile',{...d,id}));}
 if(action==='explain')return explain(id);if(action==='transaction')return transactionForm(id);if(action==='payment')return paymentForm(id,key);if(action==='bill')return billForm(id,kind);if(action==='event')return eventDialog(id);if(action==='need')return needForm(id);if(action==='income')return incomeForm(id);if(action==='incomeHistory')return incomeHistory(id);if(action==='incomeDepositReview'){await write('incomeDepositReview',{incomeId:el.dataset.incomeId,transactionId:id,mode:el.dataset.mode});return incomeHistory(el.dataset.incomeId);}if(action==='incomeDismissed')return incomeDismissed();if(action==='goal')return goalForm(id,kind);if(action==='afford')return afford();if(action==='trip')return tripForm(id);if(action==='tripResult')return tripResult(id);if(action==='estimateTrip')return tripEstimate();if(action==='suggestTrip')return tripSuggestions();if(action==='chooseTripDate'){$('#edit-form').elements.start.value=id;$('#edit-form').elements.end.value=el.dataset.end;return;}
 if(action==='selectDay'){selectedDay=id;$('#day-details').innerHTML=dayDetails();document.querySelectorAll('.calendar-grid .day').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));return;}if(action==='dayAdd'){billForm('','Planned');$('#edit-form').elements.date.value=id;return;}if(action==='purgeBill')return purgeBillDialog(B.deletedBills.find(b=>b.id===id),id);if(action==='restoreBill')return await write('restoreBill',{id});if(action==='month'){const d=new Date(calendarMonth+'-01T00:00:00Z');if(id==='0')calendarMonth=S.asOf.slice(0,7);else{d.setUTCMonth(d.getUTCMonth()+Number(id));calendarMonth=d.toISOString().slice(0,7);}selectedDay=id==='0'?S.asOf:'';if(location.hash==='calendar/'+calendarMonth||location.hash==='#calendar/'+calendarMonth){await render();return;}location.hash='calendar/'+calendarMonth;return;}
 if(action==='restoreOccurrence')return await write('restoreOccurrence',{key:id});
 if(action==='skip')return show('Skip This Bill Occurrence?',`<p>Skip only ${date}. This removes its amount from upcoming bills and forecasts.</p>`,()=>write('occurrence',{key:id,date,status:'Skipped'}));
 if(action==='billPaid')return show('Record Paid Bill',select('Pay With','accountId',S.accounts.filter(a=>['cash','credit'].includes(a.kind)).map(a=>[a.id,a.name+(a.kind==='credit'?' · Credit Card':' · Cash')]),''),d=>write('occurrence',{...d,key:id,date,status:'Paid'}));
 if(action==='referenceAccount'){const a=S.accounts.find(a=>a.id===id);return show(a.name,`<p>${esc(provenance(a))}</p><p>${dollars(a.balance)} · ${a.apr}% APR</p><div class="actions">${btn('Record Payment','payment',id)}${btn('Edit Account','account',id)}</div>`);}
 if(action==='incomeOptions')return incomeOptions(id);
 if(action==='receive'){const i=B.incomes.find(i=>i.id===id);return show('Paycheck Received',`${input('Deposit Amount','amount',budgetAnalysis().income.find(v=>v.id===i.id)?.amount??i.amount,'number','min="0" step="0.01" required')}${input('Deposit Date','date',S.asOf,'date',`required max="${S.asOf}"`)}${select('Deposited Into','accountId',accounts(),'')}${select('Balance','addToBalance',[['','Already in my bank balance (or coming from the bank import)'],['yes','Add this deposit to my balance (cash or cheque)']],'')}<p>Clearing the paycheck does not change your balance. Your bank deposit does that when it imports. Choose the second option only for pay your bank will never show.</p>`,d=>write('receiveIncome',{...d,addToBalance:d.addToBalance==='yes',id,expectedDate:date||undefined}));}
 if(action==='preferences')return location.hash='#home';
 if(action==='remove')return removeDialog(list,id);
 if(action==='decision')return show('Decision or Win',input('Title','name','','text','required')+'<label>Notes<textarea name="notes" rows="4"></textarea></label>',d=>write('decision',d));
 if(action==='cooling')return show('Pause a Purchase',input('Item','name','','text','required')+input('Cost','cost','','number','min="0" step="0.01" required')+select('Revisit in','days',[['1','1 day'],['3','3 days'],['7','1 week'],['30','30 days']],'3'),d=>write('cooling',d));
 if(action==='history')return await historyDialog();if(action==='backupNow'){await api('backup',{});successNotice('Backup Saved');return;}if(action==='preview'){const p=await api('preview',{kind,id});return show('Preview Recovery',`<p>${esc(p.label)}</p><p>${p.accounts} accounts · ${p.transactions} transactions · ${p.payments} payments</p><p>Snapshot saved: ${esc(p.savedAt)}. This replaces the current budget; a backup of the current version is saved first.</p>`,async()=>{const d=await api('restore',{token:p.token});B=d.book;S=d.summary;close();await render();successNotice('Recovery Completed');});}
 if(action==='export'){const data=await api(action),a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download='Budget-HQ-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='reviewImports')return reviewImports();if(action==='acceptHistory'||action==='discardHistory'){const ids=[...document.querySelectorAll('[data-import]:checked')].map(c=>c.dataset.import);if(!ids.length)throw Error('Select at least one record.');return await write('reviewHistory',{ids,accept:action==='acceptHistory'});}
 if(action==='logout'){await api('owner/logout',{});location.replace('/login');return;}
 }catch(err){if(action.startsWith('plaid')){setPlaidRefreshWarning(err.message);await refreshPlaidPanel();}else if($('#form-error'))$('#form-error').textContent=err.message;else notice(err.message);}});
document.addEventListener('change',async e=>{if(e.target.name==='estimateMode'){const form=e.target.closest('#edit-form');form?.querySelectorAll('[data-income-method]').forEach(panel=>panel.hidden=panel.dataset.incomeMethod!==e.target.value);return;}if(e.target.matches?.('[data-forecast-date]')&&e.target.value)return inspectPlanDay(e.target.value);if(e.target.dataset.category)try{await write('category',{id:e.target.dataset.category,category:e.target.value});}catch(err){notice(err.message);await load();}});
document.addEventListener('input',e=>{if(e.target.id==='tx-search'){const q=e.target.value.toLowerCase();$('#tx-rows').innerHTML=transactionRows(B.transactions.filter(t=>t.name.toLowerCase().includes(q)||(B.accounts.find(a=>a.id===t.accountId)?.name||'').toLowerCase().includes(q)));}});
window.addEventListener('hashchange',()=>{close();render().catch(e=>notice(e.message));});
if(window.visualViewport){const resize=()=>{document.documentElement.style.setProperty('--viewport-height',window.visualViewport.height+'px');document.documentElement.style.setProperty('--viewport-top',window.visualViewport.offsetTop+'px');};window.visualViewport.addEventListener('resize',resize);window.visualViewport.addEventListener('scroll',resize);resize();}

// Consolidated spreadsheet capabilities; all displays use the shared analysis.
function budgetAnalysis(){return S.analysis||analyzeBudget(B,S);}
function dataTable(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
uiIconPaths.income=uiIconPaths.wallet;uiIconPaths.insights=uiIconPaths.intelligence;
function incomeSourcesPage(){
 const a=budgetAnalysis(),modeName={average:'Typical',conservative:'Cautious',manual:'Entered',wages:'Hourly'};
 return readiness()+card('Income Sources',`<p>Receiving a deposit records cash once and advances its schedule.</p><div class="income-source-list">${a.income.map(i=>{const source=B.incomes.find(v=>v.id===i.id),decision=incomeForecastDecision(B,source,S.asOf),next=S.nextPaychecks.find(e=>e.id===i.id);return `<details class="income-source-row"><summary class="income-source-summary"><span class="icon-badge tone-mint">${uiIcon('wallet')}</span><span class="income-source-copy"><strong>${esc(i.name)}</strong><small>${next?'Next payday '+shortDate(next.date):'No paycheck in the next 60 days'} · ${esc(i.confidence)}</small></span><span class="income-plan-amount"><span class="amount-bubble tone-mint">${decision.forecast?dollars(decision.forecast.amount):'Not forecast'}</span></span><span class="item-chevron" aria-hidden="true">›</span></summary><div class="income-source-details"><small>${esc(source.frequency)} · ${modeName[i.mode]||'Entered'} · ${i.count} deposits used${i.lastDeposit?' · Last '+shortDate(i.lastDeposit):''}${decision.reason?' · '+esc(decision.reason):''}</small><small>Entered: ${dollars(source.amount)} · Typical: ${i.enough?dollars(i.typical):'Needs history'} · Cautious: ${i.enough?dollars(i.conservative):'Needs history'}</small>${i.outliers?.length?`<small>${i.outliers.length} deposit(s) excluded from the estimate · review History</small>`:''}<div class="income-source-actions">${btn('History','incomeHistory',i.id)}${btn('Edit','income',i.id)}${btn('Received','receive',i.id)}${remove('incomes',i.id)}</div></div></details>`;}).join('')||empty('Add your first income source.')}</div>`,btn('Add Income Source','income'));
}
function incomeHistory(id){const i=budgetAnalysis().income.find(v=>v.id===id);if(!i)return;const source=B.incomes.find(v=>v.id===id),overrides=source.depositEstimateOverrides||{},variance=i.variance.length?dataTable(['Date','Expected','Received','Difference'],i.variance.map(v=>[shortDate(v.date),dollars(v.expected),dollars(v.actual),amount(v.difference)])):empty('Variance appears after you record a scheduled deposit.');const excluded=new Set((i.outliers||[]).map(v=>v.id)),deposits=i.rows.length?dataTable(['Date','Deposit','Estimate','Review'],i.rows.map(v=>[shortDate(v.date),dollars(v.amount),overrides[v.id]===true?'Included by you':overrides[v.id]===false?'Excluded by you':excluded.has(v.id)?'Excluded as unusual':'Included automatically',btn(excluded.has(v.id)?'Use in estimate':'Exclude','incomeDepositReview',v.id,'data-income-id="'+esc(id)+'" data-mode="'+(excluded.has(v.id)?'include':'exclude')+'" aria-label="'+(excluded.has(v.id)?'Use':'Exclude')+' '+esc(dollars(v.amount))+' deposit from '+shortDate(v.date)+' in estimate"')+(v.id in overrides?btn('Use automatic','incomeDepositReview',v.id,'data-income-id="'+esc(id)+'" data-mode="automatic" aria-label="Use automatic estimate decision for '+esc(dollars(v.amount))+' deposit from '+shortDate(v.date)+'"'):'')] )):empty('No matching deposits found in the last eight weeks.');show('Income History',`<p>${esc(i.name)} · ${esc(i.confidence)} · ${i.matchedCount??i.count} matching deposits in the last eight weeks; ${i.count} used for the estimate.${i.lastDeposit?' Last matching deposit: '+shortDate(i.lastDeposit)+'.':''}${i.missedPaydays?' '+i.missedPaydays+' expected pay period(s) have no matching deposit. Review the schedule and bank activity.':''}</p><p>Typical: ${i.enough?dollars(i.typical):'Needs history'} · Cautious: ${i.enough?dollars(i.conservative):'Needs history'}${i.outliers?.length?' · '+i.outliers.length+' deposit(s) excluded from these estimates':''}.</p><p>Review changes future estimates only. Your recorded cash and transactions stay as they are.</p><h3>Predicted vs Actual</h3>${variance}<h3>Deposits</h3>${deposits}`);}
function incomeForm(id){const i=B.incomes.find(i=>i.id===id)||{date:S.asOf,frequency:'Biweekly',amount:0},mode=['average','conservative','manual','wages'].includes(i.estimateMode)?i.estimateMode:'average';show('Income Source',`<div class="fields">${input('Employer / Source','name',i.name,'text','required')}${input('Next Payday','date',i.date,'date','required')}${select('Pay Frequency','frequency',freq,i.frequency)}${input('Expected Take-home Pay','amount',i.amount,'number','min="0" step="0.01" required')}${select('Estimate Method','estimateMode',[['average','Typical deposits'],['conservative','Cautious deposits'],['manual','Entered amount'],['wages','Hourly wage']],mode)}${input('Deposit Name in Transactions','historyName',i.historyName||i.name)}</div><div data-income-method="wages" ${mode==='wages'?'':'hidden'}><div class="fields">${input('Hourly Wage','hourlyRate',i.hourlyRate||0,'number','min="0" step="0.01"')}${input('Hours per Week','hoursPerWeek',i.hoursPerWeek||0,'number','min="0" max="168" step="0.01"')}${input('Take-home Percentage','takeHomePercent',i.takeHomePercent??100,'number','min="0" max="100" step="0.01"')}</div></div><p>Expected Take-home Pay is used for entered estimates and as a fallback while deposit history builds. Typical uses the recent matching deposit average. Cautious lowers it for variation. Both use the entered amount until there is enough history. Hourly uses wage, weekly hours and take-home percentage.</p><p>Received records cash once and advances this schedule.</p>`,d=>write('incomeProfile',{...d,id}));}
