function staticKpi(...args){return originalKpi(...args).replace(' safe-spend-card','').replace(/^<button /,'<div ').replace(/ data-action="[^"]*" data-id="[^"]*"/,'').replace(/<\/button>$/,'</div>');}
function debtProgress(a){
 if(a.kind!=='credit')return `<div class="debt-progress"><progress max="100" value="${paidProgress(a)}"></progress><small>${paidProgress(a).toFixed(1)}% paid off</small></div>`;
 if(!(a.limit>0))return '<div class="debt-progress"><small>Add credit limit to show utilization</small></div>';
 const used=Math.max(0,a.balance/a.limit*100),color=used<10?'#23835b':used<30?'#b48713':used<50?'#d97521':'#c53c46';
 return `<div class="debt-progress credit-utilization" style="--utilization-color:${color}"><progress aria-label="Credit utilization" aria-valuetext="${used.toFixed(1)}% of credit limit used" max="100" value="${Math.min(100,used)}"></progress><small>${used.toFixed(1)}% used${used>100?' · over limit':''}</small></div>`;
}
function paidProgress(a){const base=a.kind==='credit'?a.openingBalance:(a.original||a.openingBalance);return base>0?Math.max(0,Math.min(100,(1-a.balance/base)*100)):a.balance<=0?100:0;}

function debtPageBase(){const debts=S.accounts.filter(a=>a.kind!=='cash'),strategy=B.settings.debtStrategy||'avalanche',ordered=debts.filter(a=>a.balance>0).sort((a,b)=>a.id===B.settings.priorityDebt?-1:b.id===B.settings.priorityDebt?1:strategy==='snowball'?a.balance-b.balance:b.apr-a.apr||a.balance-b.balance),target=ordered[0],pool=budgetAnalysis().allocation?.parts.debt||0,groups=[['Credit Cards',a=>a.kind==='credit'],['Student Loans',a=>a.kind==='loan'&&(a.debtCategory||(a.debtType==='personal'?'personal':/student/i.test(a.name)?'student':''))==='student'],['Car Loan',a=>a.kind==='loan'&&(a.debtCategory||(a.debtType==='personal'?'personal':/car|auto|forester/i.test(a.name)?'car':''))==='car'],['Personal Debts',a=>a.kind==='loan'&&(a.debtCategory||(a.debtType==='personal'?'personal':/student/i.test(a.name)?'student':/car|auto|forester/i.test(a.name)?'car':'personal'))==='personal'],['Other Loans',a=>a.kind==='loan'&&a.debtCategory==='other']];return readiness()+`<div class="grid kpis">${originalKpi('Total Debt',dollars(debts.reduce((n,a)=>n+a.balance,0)),'Recorded balances','debtAccounts')}${originalKpi('Debt Accounts',debts.length,'Manage debt records','debtAccounts')}${originalKpi('Recorded Payments',B.payments.length,'All-time payment history','recordedPayments')}${originalKpi('Next Target',target?esc(target.name):'Paid Off','Suggested extra: '+dollars(pool)+' next paycheck','snowballTarget')}</div>`+card('Your Debt Accounts',groups.map(([label,filter])=>{const list=debts.filter(filter);return list.length?`<div class="reference-debt-group"><div class="debt-group-title"><b>${label}</b><span>${dollars(list.reduce((n,a)=>n+a.balance,0))}</span></div>${list.map(a=>`<details class="inline-debt"><summary class="reference-debt-row">${iconBadge(debtIcon(a))}<div><b>${esc(a.name)}</b><small>${dollars(a.balance)} · ${a.apr}% APR · ${dollars(a.payment)} / ${esc(a.frequency)}</small></div>${debtProgress(a)}<span class="item-chevron">›</span></summary><div class="item-options actions">${btn('Record Payment','payment',a.id)}${btn('Edit','account',a.id)}${btn('Delete','remove',a.id,'data-list="accounts"','danger')}<p>${esc(provenance(a))}</p><p>Progress is measured against ${dollars(a.kind==='credit'?a.openingBalance:(a.original||a.openingBalance))}${a.kind==='credit'?' starting balance':' original balance'}. New borrowing or balance edits can reduce progress.</p></div></details>`).join('')}</div>`:'';}).join('')||empty('No debt accounts.'),btn('Add Debt Account','account','','data-kind="loan"'))+card('Recorded Payments',paymentHistory())+debtProjection();};

function financialAllocationDetails(book,data,allocation,{nextTarget=false}={}){
 if(!allocation)return {pool:0,rows:[],markup:empty('No paycheck is scheduled.')};
 const pools=allocation.parts,keys=['debt','sinking','goals','wishes'],pool=keys.reduce((n,k)=>n+(pools[k]||0),0),days=Math.max(1,(Date.parse(allocation.until||allocation.date)-Date.parse(allocation.date)+86400000)/604800000),groups={debt:[],sinking:[],goals:[],wishes:[]};
 const debts=data.accounts.filter(a=>a.active!==false&&a.kind!=='cash'&&a.balance>0),strategy=book.settings.debtStrategy||'avalanche',milestone=book.settings.priorityTarget?.list==='goals'?book.goals.find(g=>g.id===book.settings.priorityTarget.id&&g.goalType==='debt'):null,linked=milestone&&debts.find(a=>a.id===milestone.debtId),target=linked||debts.sort((a,b)=>a.id===book.settings.priorityDebt?-1:b.id===book.settings.priorityDebt?1:strategy==='snowball'?a.balance-b.balance:b.apr-a.apr||a.balance-b.balance)[0];
 if((pools.debt||0)>0){const milestoneName=target&&book.goals.find(g=>g.goalType==='debt'&&g.debtId===target.id)?.name;groups.debt.push({icon:milestoneName?'target':'extraDebt',tone:milestoneName?'lav':'gold',name:milestoneName?milestoneName+' - Additional debt payment':target?'Extra payment · '+target.name:'Extra debt payment',amount:pools.debt,debtId:target?.id});}
 const targetDate=allocation.date;
 for(const list of ['goals','wishes','sinking']){
  let left=pools[list]||0;if(!left)continue;
  const targets=(book[list]||[]).filter(g=>g.active!==false&&!(list==='goals'&&g.goalType==='debt')&&effectiveSavingsStyle(g,targetDate)!=='Pause'&&Number(g.saved||0)<Number(list==='goals'?goalTarget(g,book):g.cost||0)&&!(list==='wishes'&&wishPauseState(g,book,targetDate,data).paused));
  const cost=g=>Number(list==='goals'?goalTarget(g,book):g.cost||0),selected=book.settings.priorityTarget,amounts=new Map();
  for(const g of targets.filter(g=>effectiveSavingsStyle(g,targetDate)==='Custom')){const amount=Math.min(left,Math.max(0,Number(g.weekly)||0)*days,Math.max(0,cost(g)-Number(g.saved||0)));amounts.set(g.id,amount);left=Math.round((left-amount)*100)/100;}
  const automatic=targets.filter(g=>effectiveSavingsStyle(g,targetDate)==='Automatic');
  while(left>.009&&automatic.some(g=>cost(g)-Number(g.saved||0)-(amounts.get(g.id)||0)>.009)){
   const open=automatic.filter(g=>cost(g)-Number(g.saved||0)-(amounts.get(g.id)||0)>.009),total=open.reduce((n,g)=>n+(selected?.list===list&&selected.id===g.id?2:1),0),share=left;let used=0;
   for(const g of open){const weight=selected?.list===list&&selected.id===g.id?2:1,amount=Math.min(Math.max(0,cost(g)-Number(g.saved||0)-(amounts.get(g.id)||0)),Math.round(share*weight/(total||1)*100)/100);amounts.set(g.id,(amounts.get(g.id)||0)+amount);used=Math.round((used+amount)*100)/100;}
   if(used<.01)break;left=Math.round((left-used)*100)/100;
  }
  for(const g of targets){const amount=Math.round((amounts.get(g.id)||0)*100)/100;if(amount>.005)groups[list].push({icon:list==='wishes'?'heart':list==='sinking'?'sinking':'target',tone:list==='wishes'?'rose':list==='sinking'?'blue':'lav',name:g.name,amount,goalId:g.id});}
 }
 const assigned=Object.values(groups).flat().reduce((n,x)=>n+x.amount,0),unassigned=Math.max(0,Math.round((pool-assigned)*100)/100);
 if(unassigned>.005)groups.goals.push({icon:'wallet',tone:'neutral',name:'Not assigned to an active target',amount:unassigned});
 const items=Object.values(groups).flat(),labels={debt:['extraDebt','gold','Extra Debt'],sinking:['sinking','blue','Sinking Funds'],goals:['target','lav','Saving Goals'],wishes:['heart','rose','Wishes']},markup=keys.map(k=>{const [icon,tone,label]=labels[k],value=pools[k]||0,rows=groups[k].map(x=>'<div class="financial-target-allocation-row">'+iconBadge(x.icon,x.tone)+'<span>'+esc(x.name)+'<small>'+((allocation.surplus>0?100*x.amount/allocation.surplus:0).toFixed(1).replace(/\.0$/,'')+'% of optional surplus')+'</small></span><b>'+dollars(x.amount)+'</b></div>').join('');return '<div class="financial-allocation-category"><div class="paycheck-allocation-row">'+iconBadge(icon,tone)+'<div><b>'+label+'</b><small>Share of optional surplus</small></div><span class="allocation-amount">'+dollars(value)+'</span><span class="amount-bubble tone-'+tone+'">'+(allocation.surplus?100*value/allocation.surplus:0).toFixed(1).replace(/\.0$/,'')+'%</span></div>'+rows+'</div>';}).join(''),summaryMarkup=keys.map(k=>{const [icon,tone,label]=labels[k],value=pools[k]||0;return '<div class="financial-allocation-category"><div class="paycheck-allocation-row">'+iconBadge(icon,tone)+'<div><b>'+label+'</b><small>Share of optional surplus</small></div><span class="allocation-amount">'+dollars(value)+'</span><span class="amount-bubble tone-'+tone+'">'+(allocation.surplus?100*value/allocation.surplus:0).toFixed(1).replace(/\.0$/,'')+'%</span></div></div>';}).join('');
 return {pool,rows:items,groups,markup,summaryMarkup};
}

function paycheckAllocationDetailsFor(period,book=B,data=S,options={}){
 if(!period)return null;
 const goalRows=projectGoalSavings(book,data).rows,wishRows=projectWishSavings(book,data).rows,priorGoals=goalRows.filter(r=>r.date<period.date).reduce((n,r)=>n+r.contribution,0),priorWishes=wishRows.filter(r=>r.date<period.date).reduce((n,r)=>n+r.contribution,0),paycheckData={...data,nextPaychecks:data.nextPaychecks.filter(i=>i.date>=period.date)},allocation=allocatePaycheck(book,paycheckData,{reserved:priorGoals+priorWishes});
 if(!allocation)return null;
 const goalContribution=goalRows.find(r=>r.date===period.date)?.contribution||0,wishContribution=wishRows.find(r=>r.date===period.date)?.contribution||0,unassignedGoals=Math.max(0,allocation.parts.goals-goalContribution),unassignedWishes=Math.max(0,allocation.parts.wishes-wishContribution);
 allocation.parts.goals=goalContribution;allocation.parts.wishes=wishContribution;allocation.parts.flex=Math.round((allocation.parts.flex+unassignedGoals+unassignedWishes)*100)/100;
 return {allocation,financial:financialAllocationDetails(book,paycheckData,allocation,options)};
}

function financialGoalPaycheckAllocations(book=B,data=S){
 const projected=projectGoalSavings(book,data),goals=book.goals,milestones=goals.filter(g=>g.goalType==='debt'&&g.active!==false),periods=buildPlan(book,data).periods;
 const rows=projected.rows.map(r=>{
  const period=periods.find(p=>p.date===r.date),detail=period&&paycheckAllocationDetailsFor(period,book,data);let allocated=0;
  for(const item of detail?.financial.groups.goals||[])if(item.goalId&&goals.some(g=>g.id===item.goalId&&g.goalType!=='debt'))allocated+=item.amount;
  const countedDebtAccounts=new Set();for(const goal of milestones){if(!goal.debtId||countedDebtAccounts.has(goal.debtId))continue;countedDebtAccounts.add(goal.debtId);allocated+=(detail?.financial.groups.debt||[]).filter(e=>e.debtId===goal.debtId).reduce((n,e)=>n+e.amount,0);}
  return {date:r.date,amount:r.amount,allocated:Math.round(allocated*100)/100};
 });
 return {rows,total:Math.round(rows.reduce((n,r)=>n+r.allocated,0)*100)/100};
}

