function projectSinkingFundSavings(){
 const points=S.plan.forecast.slice(0,60),funds=B.sinking.filter(f=>f.active!==false),alreadySaved=funds.reduce((n,f)=>n+Number(f.saved||0),0),dates=buildPlan(B,S).periods.filter(p=>points.some(day=>day.date===p.date)),goalProjection=projectGoalSavings(B,S),wishProjection=projectWishSavings(B,S),funded=new Map(funds.map(f=>[f.id,Number(f.saved)||0]));let reserved=0;
 const rows=dates.map((period,index)=>{
  const detail=paycheckAllocationDetailsFor(period),nextDate=dates[index+1]?.date,priorGoals=goalProjection.rows.filter(r=>r.date<period.date).reduce((n,r)=>n+r.contribution,0),priorWishes=wishProjection.rows.filter(r=>r.date<period.date).reduce((n,r)=>n+r.contribution,0),tail=points.filter(p=>p.date>=period.date&&(!nextDate||p.date<nextDate)),headroom=Math.max(0,Math.round((Math.min(...tail.map(p=>p.cash))-S.cash.bufferTarget-priorGoals-priorWishes-reserved)*100)/100),requests=(detail?.financial.groups.sinking||[]).map(item=>{const fund=funds.find(f=>f.id===item.goalId),remaining=fund&&effectiveSavingsStyle(fund,period.date)!=='Pause'?Math.max(0,Number(fund.cost||0)-(funded.get(fund.id)||0)):0;return {id:item.goalId,amount:Math.min(item.amount,remaining)};}).filter(x=>x.amount>.005),requested=requests.reduce((n,x)=>n+x.amount,0);let contribution=S.ready?Math.round(Math.min(requested,headroom)*100)/100:0,left=contribution;
  for(const request of requests){const amount=Math.min(left,request.amount);funded.set(request.id,Math.round(((funded.get(request.id)||0)+amount)*100)/100);left=Math.round((left-amount)*100)/100;if(left<.005)break;}
  reserved=Math.round((reserved+contribution)*100)/100;
  const remaining=funds.reduce((n,f)=>n+Math.max(0,Number(f.cost||0)-(funded.get(f.id)||0)),0);
  return {date:period.date,amount:period.amount,contribution,projectedSaved:Math.round((alreadySaved+reserved)*100)/100,reason:!S.ready?'Confirm planning setup':!remaining?'No active unfunded sinking funds':contribution?'Sinking Funds allocation reserved':!requested?'No Sinking Funds allocation':!headroom?'Protecting your buffer':'No paycheck surplus available'};
 });
 return {alreadySaved,projectedContributions:reserved,projectedSaved:Math.round((alreadySaved+reserved)*100)/100,rows,end:points.at(-1)?.date||S.asOf};
}
