// PC mockup presentation — existing ledger operations and data stores are retained.
function timelineDate(date){
 const d=new Date(date+'T12:00:00Z');
 return '<time class="expense-date" datetime="'+esc(date)+'"><span>'+new Intl.DateTimeFormat('en-US',{weekday:'short',timeZone:'UTC'}).format(d)+'</span><b>'+new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(d)+'</b></time>';
}
function activityRows(items){return items.map(e=>{
 const income=!!e.inflow,tone=calendarEventTone(e);
 const recurring=!!e.debtId||B.bills.find(b=>b.id===e.id)?.frequency!=='One-time';
 const actions=income?'<div class="actions">'+btn('Received','receive',e.id,'data-date="'+e.date+'"')+btn('Edit','income',e.id)+trashButton('deleteScheduled',e.key||e.id+'@'+e.date,'','Delete This Paycheck')+'</div>':'<div class="actions">'+(recurring?btn('Skip','skip',e.key,'data-date="'+e.date+'"'):'')+(e.debtId?btn('Record Payment','payment',e.debtId,'data-key="'+e.key+'"'):btn('Mark Paid','billPaid',e.key,'data-date="'+e.date+'"'))+btn('Edit',e.debtId?'account':'bill',e.id)+(e.debtId?trashButton('deleteScheduled',e.key,'','Delete This Scheduled Payment'):trashButton('remove',e.id,'data-list="bills"','Delete Expense'))+'</div>';
 return '<details class="timeline-item '+(income?'income':'')+'" data-section-key="activity-'+esc(e.key||e.id+'@'+e.date)+'"><summary class="timeline-summary">'+timelineDate(e.date)+'<span class="timeline-divider" aria-hidden="true"></span>'+iconBadge(income?'income':typeIcon(e),tone)+'<span class="item-copy"><strong>'+esc(e.name)+'</strong><small>'+(income?'Expected Income':esc(expenseCategory(e)))+'</small></span><span class="amount-bubble tone-'+tone+'">'+(income?'+':'')+dollars(e.amount)+'</span><span class="item-chevron" aria-hidden="true">›</span></summary><div class="item-options">'+actions+'</div></details>';
 }).join('')||empty('Nothing scheduled.');
};
