function safeSection(key,icon,tone,label,note,value,body){return '<details class="safe-reserved safe-section" data-section-key="safe-'+key+'"><summary>'+moneyLine(icon,tone,label,note,value)+'<span class="safe-chevron" aria-hidden="true">'+uiIcon('expand')+'</span></summary>'+body+'</details>';}

function budgetSearchResults(query){
 const q=query.trim().toLowerCase();
 if(!q)return '<p class="empty">Search for a bill, account, need, wish, goal, or income source.</p>';
 const groups=[['Accounts',S.accounts,'account','wallet'],['Bills',B.bills,'bill','calendar'],['Needs',B.needs,'need','plus'],['Wishes',B.wishes,'goal','heart','wish'],['Goals',B.goals,'goal','goals','goal'],['Sinking Funds',B.sinking,'goal','wallet','sinking'],['Income',B.incomes,'income','wallet']];
 const results=groups.flatMap(([label,items,action,icon,kind])=>items.filter(item=>String(item.name||'').toLowerCase().includes(q)).map(item=>btn(iconBadge(icon,'blue')+'<span><strong>'+esc(item.name)+'</strong><small>'+label+'</small></span><span class="item-chevron">›</span>',action,item.id,kind?'data-kind="'+kind+'"':'','search-result')));
 return results.slice(0,40).join('')||'<p class="empty">Nothing matches that search.</p>';
}

