function input(label,name,value='',type='text',extra=''){
 const html=plainInput(label,name,value,type,extra);
 if(type!=='number'||!/^(amount|cost|saved|weekly|purchase|buffer|balance|currentBalance|openingBalance|limit|original|payment|principal|extraWeekly|hourlyRate|potentialSavings)$/.test(name))return html;
 return html.replace('<input','<span class="currency-input"><span aria-hidden="true">$</span><input inputmode="decimal"').replace('</label>','</span></label>');
};
function trashButton(action,id,extra='',label='Remove'){return btn(uiIcon('trash'),action,id,extra+' aria-label="'+esc(label)+'" title="'+esc(label)+'"','danger trash-button');}
function priorityIcon(priority){return priority==='High'?'warning':priority==='Medium'?'flag':'leaf';}
function priorityTone(priority){return priority==='High'?'red':priority==='Medium'?'gold':'leaf';}
function readOnlyActivity(items){return items.map(e=>'<div class="readonly-activity">'+iconBadge(e.inflow?'income':typeIcon(e),calendarEventTone(e))+'<div><strong>'+esc(e.name)+'</strong><small>'+shortDate(e.date)+'</small></div><span class="amount-bubble tone-'+calendarEventTone(e)+'">'+(e.inflow?'+':'')+dollars(e.amount)+'</span></div>').join('')||empty('Nothing here.');}
function thisWeekRows(){return activityRows([...S.upcoming,...S.nextPaychecks.map(e=>({...e,inflow:true}))].filter(e=>e.date>=S.asOf&&e.date<=add(S.asOf,6)).sort((a,b)=>a.date.localeCompare(b.date)||a.name.localeCompare(b.name)));};

function needForm(id,mode='later'){
 const n=B.needs.find(x=>x.id===id)||{urgency:'Medium'};
 show('Plan a Need','<div class="fields need-fields">'+input('What Needs Doing?','name',n.name,'text','required')+input('Your Exact Cost','cost',n.cost,'number','min="0.01" step="0.01" required')+
 select('Bill Category','category',[['','Automatic'],...EXPENSE_CATEGORIES],n.category||'')+
 '<fieldset class="priority-options"><legend>Priority</legend>'+['High','Medium','Low'].map(p=>'<label class="priority-choice"><input type="radio" name="urgency" value="'+p+'" '+(n.urgency===p?'checked':'')+'>'+iconBadge(priorityIcon(p),priorityTone(p))+'<span>'+p+'</span></label>').join('')+'</fieldset>'+
 '<fieldset class="date-options"><legend>Scheduling</legend>'+[['later','Keep as a Need'],['suggested','Suggested Date'],['custom','Select a Date']].map(([v,l])=>'<label><input type="radio" name="dateMode" value="'+v+'" '+(mode===v?'checked':'')+'>'+l+'</label>').join('')+'</fieldset>'+
 '<div data-custom-date>'+input('Select a Date','date',S.asOf,'date','min="'+S.asOf+'"')+'</div></div><p id="need-suggestion"></p>',
 d=>{if(d.dateMode==='suggested'){d.date=needDate(d.cost,d.urgency);if(!d.date)throw Error('No suitable suggested date. Select a date or keep this as a Need.');}if(d.dateMode!=='later'&&d.date<S.asOf)throw Error('Choose today or a future date.');return write('need',{...d,id,mode:d.dateMode==='later'?'save':'schedule'});});
 bindConditionalForm('need');const f=$('#edit-form');f.addEventListener('change',updateNeedDate);f.elements.cost.addEventListener('input',updateNeedDate);updateNeedDate();
};

let weeklyDraft=null,weeklyReturn='',writingFromCheckin=false;

async function write(action,data){
 writingFromCheckin=true;try{await saveChange(action,data);}finally{writingFromCheckin=false;}
 if(weeklyReturn&&action!=='checkin'){
  if(weeklyReturn==='bills')checkinBills();
  else if(['account','editAccount','confirmBalance','reconcile'].includes(action)){accountsDialog();$('#modal-body').innerHTML+='<div class="checkin-return">'+btn('Back to Weekly Check-in','resumeCheckin')+'</div>';}
  else checkin();
 }else if(action==='checkin'){weeklyDraft=null;weeklyReturn='';}
};

function close(){closeDialog();if(!writingFromCheckin){weeklyReturn='';weeklyDraft=null;}document.activeElement?.blur?.();const readout=$('#forecast-readout');if(readout)readout.hidden=true;};
function checkin(){
 const d=weeklyDraft||{},last=(B.checkins||[]).find(c=>c.week===weekStart(S.asOf));
 show('Weekly Check-in','<p>Week of '+shortDate(weekStart(S.asOf))+'</p>'+
 '<section class="checkin-step"><h3>1. Confirm Balances</h3><div class="checkin-balances checkin-bills">'+S.accounts.map(a=>{const icon=a.kind==='cash'?'wallet':debtIcon(a),tone=approvedIconTones[icon]||'blue';return '<div class="readonly-activity">'+iconBadge(icon,tone)+'<div><strong>'+esc(a.name)+'</strong></div><span class="amount-bubble tone-'+tone+'">'+dollars(a.balance)+'</span></div>';}).join('')+'</div>'+
 '<div class="checkin-controls">'+check('I Reviewed Current Balances','balancesReviewed',d.balancesReviewed||false)+btn('Correct Accounts First','checkinAccounts')+'</div></section>'+
 '<section class="checkin-step"><h3>2. Review Next 7 Days</h3><div class="checkin-bills">'+readOnlyActivity(S.weekBills)+'</div>'+'<div class="checkin-controls">'+check('I Reviewed Upcoming Bills','billsReviewed',d.billsReviewed||false)+btn('Correct Bills First','checkinBills')+'</div>'+'</section>'+
 '<section class="checkin-step"><h3>3. Expected Pay</h3>'+select('This Week’s Work Schedule','schedule',[['same','Same as Last Week'],['changed','Hours or Pay Changed']],d.schedule||last?.schedule||'same')+
 '<p>Changing this choice does not create a deposit. Adjust your income schedule if hours or pay changed.</p>'+readOnlyActivity(S.nextPaychecks.filter(p=>p.date<=add(S.asOf,6)).map(p=>({...p,inflow:true})))+
 '<div class="checkin-controls">'+check('I Reviewed Expected Pay','incomeReviewed',d.incomeReviewed||false)+btn('Adjust Expected Pay First','checkinIncome')+'</div></section>',d=>write('checkin',d));
};
