 const items=[...calendarEvents.filter(e=>e.date===selectedDay),...calendarRecordedEvents.filter(e=>e.date===selectedDay),...calendarIncome.filter(e=>e.date===selectedDay).map(e=>({...e,inflow:true}))];
 return '<div class="selected-day-layout"><aside>'+timelineDate(selectedDay)+'</aside><div><h3>'+selectedDateLabel(selectedDay)+'</h3>'+
 (items.map(e=>'<div class="selected-event">'+iconBadge(e.inflow?'income':typeIcon(e),calendarEventTone(e))+'<div><strong>'+esc(e.name)+'</strong><small>'+(e.inflow?'Income':esc(expenseCategory(e)))+(e.readOnly?' · Recorded':'')+'</small></div><span class="amount-bubble tone-'+calendarEventTone(e)+'">'+(e.inflow?'+':'')+dollars(e.amount)+'</span><div class="actions">'+
 (e.readOnly?'<span class="muted">Recorded · manage from Transactions or Debt</span>':e.inflow?btn('Edit','income',e.id)+btn('Received','receive',e.id):(selectedDay<S.asOf&&(B.transactions.some(t=>t.occurrenceKey===e.key)||B.payments.some(p=>p.occurrenceKey===e.key)||B.overrides[e.key]?.needMatchId)?'<span class="muted">Recorded activity linked · manage from Transactions or Debt</span>':btn('Edit',e.debtId?'account':'bill',e.id)+(e.debtId||B.bills.find(b=>b.id===e.id)?.frequency!=='One-time'?btn('Skip','skip',e.key,'data-date="'+e.date+'"'):'')+trashButton(e.debtId?'skip':'remove',e.debtId?e.key:e.id,e.debtId?'data-date="'+e.date+'"':'data-list="bills"',e.debtId?'Remove This Scheduled Occurrence':'Delete Expense')))+ '</div></div>').join('')||empty('Nothing here.'))+
 '<div class="actions day-add">'+btn('Add Expense on This Day','dayAdd',selectedDay,'','primary')+'</div></div></div>';
