function forecastGraph(points){
 let html=forecastChart(points);if(!points.length)return html;
 const i=points.reduce((a,p,j)=>p.cash<points[a].cash?j:a,0),low=points[i],lo=Math.min(0,S.cash.bufferTarget,...points.map(p=>p.cash)),hi=Math.max(S.cash.bufferTarget,...points.map(p=>p.cash)),pad=Math.max(100,(hi-lo)*.1),x=86+i*788/Math.max(1,points.length-1),y=22+(hi+pad-low.cash)/(hi-lo+2*pad)*228,bx=Math.max(90,Math.min(744,x-60));
 return html.replace('</svg>','<g class="forecast-low-label" pointer-events="none"><line x1="'+x+'" y1="77" x2="'+x+'" y2="'+y+'" stroke="#cc354a" stroke-dasharray="3 4"/><rect x="'+bx+'" y="18" width="128" height="58" rx="9" fill="white" stroke="#e0e6ec"/><text x="'+(bx+64)+'" y="35" text-anchor="middle">Low Point</text><text x="'+(bx+64)+'" y="52" text-anchor="middle" fill="'+(low.cash<0?'#bd2840':'#102843')+'">'+dollars(low.cash)+'</text><text x="'+(bx+64)+'" y="68" text-anchor="middle">'+shortDate(low.date)+'</text></g></svg>');
};

// Debt page: the base page, expanded details for each debt account, and the Total Debt / Next Target tiles.
function debt(){
 let html=debtPageBase();
 // Account details and quick actions inside each debt's expandable row
 for(const a of S.accounts.filter(a=>a.kind!=='cash')){
  const old='<div class="item-options actions">'+btn('Record Payment','payment',a.id)+btn('Edit','account',a.id)+btn('Delete','remove',a.id,'data-list="accounts"','danger');
  const start=html.indexOf(old);if(start<0)continue;
  const end=html.indexOf('</div></details>',start);if(end<0)continue;
  const fields=[['Current Balance',dollars(a.balance)],...(a.kind==='credit'?[['Credit Limit',dollars(a.limit)]]:[]),['APR',esc(a.apr)+'%'],['Scheduled Payment',dollars(a.payment)+' / '+esc(a.frequency)],['Next Due Date',a.dueDate?shortDate(a.dueDate):'Not set']];
  const replacement='<div class="item-options"><div class="debt-detail-grid"><div><h4>Account Details</h4><dl>'+fields.map(([label,value])=>'<div><dt>'+label+'</dt><dd>'+value+'</dd></div>').join('')+'</dl></div><div class="debt-detail-actions"><h4>Quick Actions</h4>'+btn(uiIcon('payment')+' Record Payment','payment',a.id)+btn('Edit Account','account',a.id)+btn('Delete Account','remove',a.id,'data-list="accounts"','danger')+'</div><p class="debt-detail-note">'+(a.kind==='credit'?'Utilization is the current balance divided by the credit limit. Bar colors: green below 10%, yellow from 10% to under 30%, orange from 30% to under 50%, red at 50% and above.':'Progress is measured against '+dollars(a.original||a.openingBalance)+' starting/original balance. New borrowing or balance edits can reduce progress.')+'</p></div>';
  html=html.slice(0,start)+replacement+html.slice(end);
 }
 // Replace the default tiles with Total Debt and Next Target
 const start=html.indexOf('<div class="grid kpis">'),end=html.indexOf('<section class="section card">',start);
 const debts=S.accounts.filter(a=>a.kind!=='cash'),target=debts.filter(a=>a.balance>0).sort((a,b)=>a.id===B.settings.priorityDebt?-1:b.id===B.settings.priorityDebt?1:B.settings.debtStrategy==='snowball'?a.balance-b.balance:b.apr-a.apr)[0];
 if(start>=0&&end>=0)html=html.slice(0,start)+'<div class="grid debt-top">'+staticKpi('Total Debt',dollars(debts.reduce((n,a)=>n+a.balance,0)),'Recorded debt balances')+originalKpi('Next Target',target?esc(target.name):'Paid Off','Extra-debt allocation: '+dollars(budgetAnalysis().allocation?.parts.debt||0),'snowballTarget')+'</div>'+html.slice(end);
 return html;
};

function nextWish(){if(wishesPausedForBuffer(S))return undefined;const waiting=new Set(B.cooling.filter(c=>c.date>S.asOf).flatMap(c=>c.wishId?[c.wishId]:B.wishes.filter(w=>w.name===c.name).map(w=>w.id)));return B.wishes.filter(w=>effectiveSavingsStyle(w,S.asOf)!=='Pause'&&w.saved<w.cost&&!waiting.has(w.id)).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.cost-a.saved)-(b.cost-b.saved))[0];}
function targetCards(list,action){return B[list].map((g,index)=>{
 const paused=list==='wishes'&&effectiveSavingsStyle(g,S.asOf)==='Pause',waiting=wishIsWaiting(g,list)||paused,picture=g.image||(list==='wishes'&&B.sampleMode?sampleWishPhoto(g.name):'');
 const p=budgetAnalysis().savings.find(v=>v.list===list&&v.id===g.id),percent=Math.max(0,Math.min(100,100*g.saved/(g.cost||1)));
 const photo=picture?'<img class="photo" referrerpolicy="no-referrer" loading="lazy" src="'+esc(picture)+'" alt="'+esc(g.name)+'">':iconBadge(action==='wish'?'heart':action==='goal'?'target':'sinking',action==='wish'?'rose':action==='goal'?'mint':'blue');
 const selected=B.settings.priorityTarget?.list===list&&B.settings.priorityTarget?.id===g.id;
 return '<article class="card reference-goal '+(picture?'with-photo ':'')+(waiting?'wish-waiting ':'')+(selected?'is-next-target':'')+'" data-target-card data-target-list="'+list+'" data-target-id="'+esc(g.id)+'">'+(g.link?'<a class="goal-photo-link" href="'+esc(g.link)+'" target="_blank" rel="noopener noreferrer" aria-label="Open '+esc(g.name)+'">'+photo+'</a>':photo)+'<div class="goal-content"><div class="goal-heading"><h3>'+esc(g.name)+'</h3><button type="button" class="target-drag-handle" data-target-drag draggable="true" aria-label="Drag to reorder '+esc(g.name)+'" title="Drag to reorder">⠿</button><strong class="positive">'+percent.toFixed(0)+'%</strong></div><p>'+dollars(g.cost)+'</p><progress max="'+(g.cost||1)+'" value="'+g.saved+'"></progress><div class="goal-stats"><span><b>'+dollars(g.saved)+'</b><small>Saved so Far</small></span><span><b>'+dollars(p?.weekly||0)+'</b><small>Suggested / Week</small></span><span><b>'+(p?.ready?shortDate(p.ready):'Not yet')+'</b><small>Projected Ready</small></span></div><div class="goal-actions">'+btn('Edit','goal',g.id,'data-kind="'+action+'"','goal-edit')+trashButton('remove',g.id,'data-list="'+list+'"','Remove '+g.name)+(action==='wish'?(wishesPausedForBuffer(S)&&!wishPauseState(g,B,S.asOf).paused?btn(uiIcon('pause')+' Auto-Paused','wishCooldown',g.id,'disabled title="Resumes automatically when your cash buffer is restored"','goal-pause'):btn(uiIcon('pause')+(wishPauseState(g,B,S.asOf).paused?' Unpause':' Pause'),wishPauseState(g,B,S.asOf).paused?'wishResume':'wishCooldown',g.id,'','goal-pause')):'')+'</div>'+(action==='wish'&&g.cost>0&&g.saved>=g.cost?'<div class="wish-complete-action">'+btn('Add to Expenses','completeTarget',g.id,'data-list="wishes"')+'</div>':'')+(action==='wish'?wishCooldownNote(g):'')+'</div></article>';
 }).join('')||empty('No targets yet.');};
