 targetPaycheckIndex=0;
 const form=$('#edit-form'),refresh=()=>{const selectedValue=form.elements.target.value||value,[list,id]=selectedValue.split(':'),goal=B[list]?.find(g=>g.id===id),category=goal?.goalType==='debt'?'debt':list,custom=form.elements.mode.value==='custom';$('#custom-allocation-fields').hidden=!custom;for(const el of $('#custom-allocation-fields').querySelectorAll('input')){el.disabled=!custom;el.required=custom;}let after;try{after=custom?Object.fromEntries(allocationKeys.map(k=>[k,Number(form.elements[k].value)])):boostAllocation(base,category);}catch{after=weights;}const simulatedBook={...B,settings:{...B.settings,allocations:after,allocationMode:custom?'custom':'automatic',priorityTarget:{list,id}}},periods=buildPlan(B,S).periods;if(!periods.length){$('#next-target-breakdown').innerHTML=empty('No upcoming paycheck allocation is available.');return;}targetPaycheckIndex=Math.max(0,Math.min(targetPaycheckIndex,periods.length-1));const period=periods[targetPaycheckIndex],projection=paycheckAllocationDetailsFor(period,simulatedBook,S,{nextTarget:true});if(!projection){$('#next-target-breakdown').innerHTML=empty('No upcoming paycheck allocation is available.');return;}const goalForecast=financialGoalPaycheckAllocations(simulatedBook,S),allocation=projection.allocation,part=(label,value,total)=>'<div class="next-target-overview-row"><span>'+label+'</span><b>'+dollars(value)+'</b><small>'+(total?100*value/total:0).toFixed(1).replace(/\.0$/,'')+'% of paycheck</small></div>';$('#next-target-breakdown').innerHTML='<div class="next-target-paycheck"><div class="paycheck-navigation"><h4>'+shortDate(period.date)+'</h4><div class="actions">'+btn('←','targetPaycheckPrevious','','aria-label="Previous paycheck" '+(targetPaycheckIndex===0?'disabled':''))+btn('→','targetPaycheckNext','','aria-label="Next paycheck" '+(targetPaycheckIndex===periods.length-1?'disabled':''))+'</div></div><p class="paycheck-expected"><strong>'+dollars(period.amount)+'</strong> expected · '+period.income.map(i=>esc(i.name)).join(' + ')+'</p><div class="next-target-overview">'+part('Bills & minimum debt payments',Math.min(period.amount,period.committed),period.amount)+part('Buffer',allocation.buffer,period.amount)+part('Flexible spending',allocation.parts.flex,allocation.surplus)+'<div class="next-target-overview-row next-target-goal-total"><span>Goals & debt milestones · full forecast</span><b>'+dollars(goalForecast.total)+'</b><small>Across upcoming paychecks</small></div></div><h4>Optional surplus allocations</h4><p class="muted">'+dollars(allocation.surplus)+' available after bills and buffer. The breakdown below is for '+shortDate(period.date)+'; the forecast total above includes both savings goal contributions and extra debt payments directed to debt milestones.</p>'+projection.financial.markup+'</div>';};
