function systemHealthMarkup(){const checks=[];const addCheck=(name,fn)=>{try{const detail=fn();checks.push({name,ok:true,detail});}catch(e){checks.push({name,ok:false,detail:e.message||'Check failed'});}};addCheck('Cash Forecast',()=>{if(!Array.isArray(S.plan?.forecast))throw Error('Forecast is unavailable');if(S.plan.forecast.some(x=>!Number.isFinite(Number(x.cash))))throw Error('A forecast balance is invalid');return S.plan.forecast.length+' daily balances calculated';});addCheck('Paycheck Allocation',()=>{const x=allocatePaycheck(B,S);if(!x?.parts||Object.values(x.parts).some(v=>!Number.isFinite(Number(v))))throw Error('Allocation returned an invalid amount');return 'Allocation amounts are valid · '+dollars(Object.values(x.parts).reduce((n,v)=>n+Number(v||0),0))+' assigned';});addCheck('Goal & Wish Projections',()=>{const g=projectGoalSavings(B,S),w=projectWishSavings(B,S);if([...g.rows,...w.rows].some(x=>!Number.isFinite(Number(x.contribution))))throw Error('A projection is invalid');return g.rows.length+' goal and '+w.rows.length+' wish paycheck projections';});addCheck('Debt Payoff',()=>{const debts=S.accounts.filter(a=>a.kind!=='cash');if(debts.some(a=>!Number.isFinite(Number(a.balance))))throw Error('A debt balance is invalid');return debts.length+' debt balances checked';});addCheck('Calendar Schedules',()=>{if(!Array.isArray(S.upcoming)||!Array.isArray(S.nextPaychecks))throw Error('Scheduled events are unavailable');if([...S.upcoming,...S.nextPaychecks].some(x=>!x.date||!Number.isFinite(Date.parse(x.date))))throw Error('A scheduled date is invalid');return S.upcoming.length+' expenses and '+S.nextPaychecks.length+' paychecks checked';});addCheck('Ledger Consistency',()=>{if(!Array.isArray(B.transactions)||!Array.isArray(B.payments))throw Error('Ledger records are unavailable');return B.transactions.length+' transactions and '+B.payments.length+' payments checked';});addCheck('Local Storage & Backups',()=>{if(runtimeCheck.startsWith('Not checked'))throw Error('Run diagnostics to verify saved backup access');if(runtimeCheck.startsWith('Check failed'))throw Error(runtimeCheck);return runtimeCheck;});addCheck('Bank Connections',()=>{if(plaidStatusError)throw Error('Connection check failed: '+plaidStatusError);if(!plaidStatus)throw Error('Connection status not loaded');if(!plaidStatus.configured)throw Error('Plaid is not configured · no bank access attempted');return (plaidStatus.items||[]).length+' bank connections checked';});addCheck('Email Reports',()=>{if(!S.mailStatus)throw Error('Email status unavailable');if(/disabled|setup needed|not configured/i.test(S.mailStatus))throw Error(S.mailStatus);return S.mailStatus;});const passed=checks.filter(x=>x.ok).length,details=checks.map(x=>row(x.name,x.detail,x.ok?'Passed':'Review'));
 const status=passed+' of '+checks.length+' checks passed';
 return '<details class="section card system-health" data-section-key="settings-system-health"><summary>'+iconBadge('health','peach')+'<span><b>System Health</b><small>'+status+(runtimeCheckedAt?' · Last checked '+esc(runtimeCheckedAt):' · Run diagnostics for a fresh check')+'</small></span><span class="item-chevron" aria-hidden="true">›</span></summary><div class="system-health-details"><p>Review calculation, storage, connection, and email checks. Diagnostics do not modify your budget.</p><div class="diagnostic-summary">'+checks.map(x=>'<div class="diagnostic-row '+(x.ok?'diagnostic-ready':'diagnostic-review')+'">'+iconBadge(x.ok?'check':'warning',x.ok?'mint':'red')+'<strong>'+esc(x.name)+'</strong><span>'+esc(x.ok?'Passed':'Review')+'</span></div>').join('')+'</div>'+btn('Run Diagnostics','systemCheck')+fold('View Diagnostic Details',details+'<p>Checks confirm that calculations return valid values; they do not verify every entered amount or bank record.</p>')+'<p>Bank transaction updates depend on the bank and may arrive later.</p></div></details>';}


