// Opens the shared dialog, then dresses it: a kicker line and fallback icon, styling tags,
// and finally the specific icon chosen from the title.
function show(title,body,handler=null){
 openDialog(title,body,handler);
 const kickerRules=[[/next target/i,'wishTarget','gold','Choose a priority and see where the money goes.'],[/safe to spend/i,'wallet','blue','A clear view of what is available.'],[/account/i,'wallet','blue','Review and manage your account details.'],[/need/i,'plus','rose','Make room for what matters next.'],[/wish/i,'heart','rose','Save toward something you will love.'],[/paycheck|income/i,'calendar','blue','Give every dollar a purpose.'],[/goal|sinking/i,'goals','lav','Build your plan, one step at a time.'],[/payment|spending/i,'payment','blue','Record it once. Keep your plan up to date.'],[/bill|expense/i,'calendar','blue','Keep track of what is coming up.'],[/health/i,'plan','lav','Understand the signals behind your score.'],[/delete|remove/i,'warning','rose','Review this change before you confirm.'],[/backup|history|restore/i,'health','mint','Keep your budget safe and recoverable.']];
 const kicker=kickerRules.find(([pattern])=>pattern.test(title))||[null,'review','blue','Your budget, with the details made clear.'];
 const symbol=$('#modal-symbol'),subtitle=$('#modal-kicker');
 if(symbol){symbol.innerHTML=uiIcon(kicker[1]);symbol.className='icon-badge tone-'+kicker[2];}
 if(subtitle)subtitle.textContent=kicker[3];
 $('#modal').setAttribute?.('data-dialog',/need/i.test(title)?'need':/wish/i.test(title)?'wish':/account/i.test(title)?'accounts':'general');
 const modal=$('#modal');if(['transactions','insights','reports'].includes(page))modal.setAttribute?.('data-tools-dialog','true');else modal.removeAttribute?.('data-tools-dialog');
 const iconRules=[[/delete|remove|discard/i,'trash','red'],[/think it over|pause wish|pause a purchase/i,'pause','gold'],[/safe to spend/i,'safeSpend','blue'],[/buffer|planning preferences/i,'buffer','peach'],[/budget health/i,'health','peach'],[/system health/i,'settings','slate'],[/compare.*duplicate/i,'duplicates','blue'],[/match.*payment/i,'match','blue'],[/import/i,'imported','teal'],[/categor/i,'uncategorized','gray'],[/weekly check/i,'weekly','lav'],[/need/i,'addNeed','mint'],[/wish/i,'heart','rose'],[/sinking/i,'sinking','blue'],[/goal/i,'target','lav'],[/afford|purchase/i,'afford','gold'],[/debt target|strategy|allocation/i,'extraDebt','gold'],[/payment/i,'payment','indigo'],[/spending|transaction/i,'spend','blue'],[/paycheck|payday|income|expected pay/i,'income','mint'],[/account/i,'reviewAccounts','blue'],[/bill|expense/i,'calendar','blue'],[/search/i,'search','blue'],[/backup|recovery|history|restore/i,'health','blue']];
 const icon=iconRules.find(([r])=>r.test(title));
 if(icon){const symbol=$('#modal-symbol');if(symbol){symbol.innerHTML=uiIcon(icon[1]);symbol.className='icon-badge tone-'+icon[2];}}
};

function requestId(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20);}

