 d.sessions.slice(-1).map(s=>'<div class="plaid-session"><div class="actions">'+btn('Check Connection','plaidFinish',s.id)+'</div></div>').join('')+
 d.items.map(i=>'<div class="plaid-connection-row">'+iconBadge('reviewAccounts','blue')+'<div><strong>'+esc(i.name)+'</strong>'+plaidStatusBadge(plaidConnectionState(i))+(i.error?warningBox('plaid-connection-'+i.id,'<small class="negative">'+esc(i.error)+'</small>'):'<small>'+(i.checkedAt?'Last successful check: '+esc(new Date(i.checkedAt).toLocaleString()):'Not checked yet')+'</small>')+'<small>Bank transactions updated: '+esc(i.bankUpdatedAt?new Date(i.bankUpdatedAt).toLocaleString():'Not provided')+'</small>'+[i.transactionsError,i.liabilitiesError,i.metadataError,i.webhookNotice,i.freshRefresh?.error,i.freshBalance?.error].filter(Boolean).map((v,n)=>warningBox('plaid-item-'+i.id+'-'+n,'<small class="negative">'+esc(v)+'</small>')).join('')+i.accounts.map(a=>'<small>'+esc(a.name)+(a.mask?' · ••'+esc(a.mask):'')+' · Balance timestamp: '+esc(a.balanceUpdatedAt?new Date(a.balanceUpdatedAt).toLocaleString():'Not provided')+'</small>').join('')+'</div><div class="actions bank-actions">'+btn('Sync Bank','plaidFresh',i.id)+btn('Change Permissions','plaidStart',i.id)+trashButton('plaidDisconnect',i.id,'','Delete Bank Connection')+'</div></div>').join('')+(!d.items.length?empty('No banks connected in this version.'):'');
