function coreDesignScreens(){if(!B||!S)return [];const list=[
 ['Current Balance',()=>accountsDialog()],['Safe to Spend',()=>explain('safe')],['Budget Health',()=>explain('health')],
 ['Next Paycheck Plan',()=>show('Next Paycheck Plan',paycheckPanel(true))],['Weekly Check-in',()=>checkin()],
 ['Plan a Need',()=>needForm()],['Add Wish',()=>goalForm('','wish')],['Financial Goal',()=>goalForm('','goal')],
 ['Sinking Fund',()=>goalForm('','sinking')],['Record Transaction',()=>transactionForm()],['Record Debt Payment',()=>paymentForm()],
 ['Add Expense',()=>billForm()],['Add Account',()=>accountForm()],['Income',()=>incomeForm()],
 ['Can I Afford This?',()=>afford()],['Goal Savings',()=>goalSavingsBreakdown()],['Financial Goal Progress',()=>financialGoalProgressDialog()],['Sinking Funds by Paycheck',()=>sinkingFundSavingsForecastDialog()]
 ];
 for(const [title,records,fn]of [['Edit Account',B.accounts,(id)=>accountForm(id)],['Edit Expense',B.bills,(id)=>billForm(id)],['Edit Need',B.needs,(id)=>needForm(id)],['Edit Wish',B.wishes,(id)=>goalForm(id,'wish')],['Pause Wish',B.wishes,(id)=>wishCooldown(id)],['Edit Financial Goal',B.goals,(id)=>goalForm(id,'goal')],['Edit Income',B.incomes,(id)=>incomeForm(id)]])if(records?.length)list.push([title,()=>fn(records[0].id)]);

 // Previews use the real confirmation renderers without inserting sample budget records.
 for(const [label,group,example] of [
 ['Delete Recurring Bill','bills',{frequency:'Monthly'}],['Delete One-time Expense','bills',{frequency:'One-time'}],
 ['Delete Account','accounts',{}],['Delete Need','needs',{}],['Delete Wish','wishes',{}],
 ['Delete Financial Goal','goals',{}],['Delete Sinking Fund','sinking',{}],['Delete Income Source','incomes',{}],
 ['Delete Transaction','transactions',{}],['Delete Received Paycheck','transactions',{incomeExpectation:true}],
 ['Remove Recorded Payment','payments',{}],['Remove Linked Payment','payments',{transactionId:'design-example'}]
 ])list.push([label,()=>removeDialog(group,'design-preview',{...example})]);
 for(const inflow of [true,false])list.push([inflow?'Delete Scheduled Paycheck':'Delete Scheduled Payment',()=>scheduledDeleteDialog({inflow,name:inflow?'Example Paycheck':'Example Debt Payment',date:S.asOf,amount:100},'design-preview')]);
 list.push(['Delete Permanently',()=>recoveryDeleteDialog('purgePayment','design-preview')]);
 for(const frequency of ['Monthly','One-time'])list.push([frequency==='Monthly'?'Permanently Delete Recurring Bill':'Permanently Delete One-time Expense',()=>purgeBillDialog({frequency,name:'Example Expense'},'design-preview')]);
 return list.map(([label,run],index)=>({label,id:String(index),open:()=>{if(!designModeActive)throw Error('Open Design Mode first.');run();}}));
}

