function scheduleIssuesPanel(){
 const known=['One-time','Weekly','Biweekly','Monthly','Quarterly','Yearly'],issues=[];
 const check=(item,debt)=>{
  const problems=[],date=debt?item.dueDate:item.date,value=debt?item.payment:item.amount;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date||'')||!Number.isFinite(Date.parse(date))||new Date(date+'T00:00:00Z').toISOString().slice(0,10)!==date)problems.push('Set a valid due date');
  if(!(Number(value)>0))problems.push('Set a payment amount');
  if(!known.includes(item.frequency))problems.push('Choose a recurrence');
  if(item.frequency==='One-time'&&date<S.asOf)problems.push('Past one-time date; choose a recurring frequency if this repeats');
  if(problems.length)issues.push(row(item.name,esc(problems.join(' · ')),btn('Edit Schedule',debt?'account':'bill',item.id)));
 };
 B.bills.filter(b=>b.active!==false).forEach(b=>check(b,false));S.accounts.filter(a=>a.active!==false&&a.kind!=='cash'&&a.balance>0).forEach(a=>check(a,true));
 return issues.length?card('Schedules Needing Attention','<p>These entries cannot produce a complete upcoming schedule. Correct the fields below to include them in calendar dates and estimates.</p>'+issues.join('')):'';
}
