// Handles button actions that the main click listener does not. Returns true when the action was handled.
// Every action name appears once; Transactions-page tools ('tools-…') are delegated to toolsUI.
async function advancedClick(action,id,list){
 if(action==='dismissWarning'){dismissPlaidWarning(id);return true;}
 // Transactions page tools
 if(await toolsUI.action(action,id,list))return true;
 if(action==='navigate'&&id==='transactions'&&page==='home'){close();location.hash='transactions/review';return true;}
 if(action==='autoCategorize'){const before=new Map(B.transactions.map(t=>[t.id,t.category]));await write('autoCategorize',{});notice(B.transactions.filter(t=>before.get(t.id)!==t.category).length+' transactions categorized.');return true;}

 // Next Paycheck Plan
 if(action==='targetPaycheckNext'||action==='targetPaycheckPrevious'){const periods=buildPlan(B,S).periods;targetPaycheckIndex=Math.max(0,Math.min(periods.length-1,targetPaycheckIndex+(action==='targetPaycheckNext'?1:-1)));refreshTargetPaycheck();return true;}
 if(action==='nextPaycheck'){paycheckIndex=0;show('Next Paycheck Plan',paycheckPanel(true));return true;}
 if(action==='paycheckNext'||action==='paycheckPrevious'){
  paycheckIndex+=action==='paycheckNext'?1:-1;
  if($('#modal').open&&$('#modal-title').textContent==='Next Paycheck Plan')$('#modal-body').innerHTML=paycheckPanel(true);
  else if($('#paycheck-plan-content'))$('#paycheck-plan-content').outerHTML=paycheckPanel();
  else await render();
  return true;
 }

 // Weekly check-in
 if(action==='checkinAccounts'||action==='checkinIncome'){weeklyDraft=formData($('#edit-form'));weeklyReturn='checkin';if(action==='checkinAccounts')accountsDialog();else show('Adjust Expected Pay',incomePage());$('#modal-body').innerHTML+='<div class="checkin-return">'+btn('Back to Weekly Check-in','resumeCheckin')+'</div>';return true;}
 if(action==='checkinBills'){weeklyDraft=formData($('#edit-form'));weeklyReturn='bills';checkinBills();return true;}
 if(action==='resumeCheckin'){checkin();return true;}
 if(action==='cashAccounts'){cashAccountsDialog();return true;}

 // Scheduled bills, income and suggestions
 if(action==='deleteScheduled'){
  const e=[...S.upcoming,...S.nextPaychecks].find(e=>(e.key||e.id+'@'+e.date)===id);
  if(!e){notice('This entry is no longer scheduled. Refresh your budget.');return true;}
  scheduledDeleteDialog(e,id);return true;
 }
 if(action==='skipRecurring'){
  const data=await api('calendar?start='+S.asOf+'&end='+add(S.asOf,370)),e=data.events.filter(e=>e.id===id&&!e.debtId&&e.date>=S.asOf).sort((a,b)=>a.date.localeCompare(b.date))[0];
  if(!e){notice('No upcoming occurrence found for this bill. Check its schedule.');return true;}
  show('Skip This Bill Occurrence?','<p>Skip '+esc(e.name)+' on '+shortDate(e.date)+'? This removes only this occurrence from upcoming bills and forecasts.</p>',()=>write('occurrence',{key:e.key,date:e.date,status:'Skipped'}));return true;
 }
 if(action==='scheduleNeed'){needForm(id,'suggested');return true;}
 if(action==='recurringReview'){recurringSuggestionForm(id);return true;}
 if(action==='recurringDismiss'){await write('recurringSuggestion',{key:id,mode:'dismiss'});return true;}
 if(action==='recurringDismissForever'){show('Dismiss Recurring Charge Permanently?','<p>This merchant will no longer appear in recurring suggestions for this account.</p>',()=>write('recurringSuggestion',{key:id,mode:'permanent'}));return true;}
 if(action==='incomeSuggestionReview'){incomeSuggestionForm(id);return true;}
 if(action==='incomeSuggestionDismiss'){await write('incomeSuggestion',{key:id,mode:'dismiss'});return true;}

 // Bank matches
 if(action==='bankMatchReview'){bankMatchForm(id);return true;}
 if(action==='bankMatchDismiss'){await write('bankMatch',{key:id,mode:'dismiss'});return true;}
 if(action==='bankMatchUnlink'){show('Unlink Bank Match','<p>Restore the linked schedule or transaction categories. Bank balances stay unchanged. Unlink later paychecks first when reversing a paycheck match.</p>',()=>write('bankMatch',{id,mode:'unlink'}));return true;}

 // Bank connections (Plaid)
 if(action==='plaidStatus'){await refreshPlaidPanel();return true;}
 if(action==='plaidConfigure'){
  show('Plaid Setup','<p>Enter your Plaid developer credentials privately here. They are encrypted on this computer and excluded from budget exports. Bank sign-in happens on Plaid’s secure page.</p>'+input('Client ID','clientId','','text','required autocomplete="off"')+input('Secret','secret','','password','required autocomplete="new-password"')+select('Environment','environment',B.sampleMode?[['sandbox','Sandbox — Test Banks']]:[['sandbox','Sandbox — Test Banks'],['production','Production — Real Banks']],plaidStatus?.environment||'sandbox'),async d=>{plaidStatus=await api('plaid/configure',d);close();await refreshPlaidPanel();successNotice('Plaid Setup Saved');});return true;
 }
 if(action==='plaidStart'){const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;try{const session=await api('plaid/start',{itemId:id||undefined});if(popup&&session.url)popup.location.href=session.url;await refreshPlaidPanel();}catch(e){if(popup)popup.close();throw e;}return true;}
 if(action==='plaidFinish'){const d=await api('plaid/finish',{id}),warning=d.accountSync?.notes?.join(' · ')||'';setPlaidRefreshWarning(warning);await load();await refreshPlaidPanel();if(warning)return true;successNotice(d.finished?'Bank Accounts Added / Updated':'Finish Plaid Sign-In, Then Check Again');return true;}
 if(action==='plaidFresh'){await refreshBankConnection(id,true);return true;}
 if(action==='plaidCheck'){await refreshBankConnection(id);return true;}
 if(action==='plaidDisconnect'){show('Disconnect This Bank?','<p>Remove its Plaid connection. Your locally recorded accounts, payments, and balances stay in your budget.</p>',async()=>{await api('plaid/disconnect',{id});close();await refreshPlaidPanel();successNotice('Bank Disconnected');});return true;}
 if(action==='resolvePlaidAccount'){accountConflictForm(id);return true;}

 // Debt
 if(action==='addPersonalDebt'){accountForm('','personal');return true;}
 if(action==='debtAccounts'){debtAccountsDialog();return true;}
 if(action==='recordedPayments'){show('Recorded Payments',paymentHistory());return true;}
 if(action==='paymentMonth'){monthlyPayments();const d=new Date(paymentMonth+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(id));paymentMonth=d.toISOString().slice(0,7);const last=paymentView==='scheduled'?(S.plan.forecast.at(-1)?.date||S.asOf).slice(0,7):paymentAnchor;if(paymentMonth>last)paymentMonth=last;if($('#modal').open&&$('#modal-title').textContent==='Recorded Payments')$('#modal-body').innerHTML=paymentHistory();else await render();return true;}
 if(action==='paymentView'){paymentView=id==='scheduled'?'scheduled':'additional';if(paymentView==='additional'&&paymentMonth>paymentAnchor)paymentMonth=paymentAnchor;if($('#modal').open&&$('#modal-title').textContent==='Recorded Payments')$('#modal-body').innerHTML=paymentHistory();else await render();return true;}
 if(action==='snowballTarget'){show('Next Debt Target',`<p>The next target follows your selected payoff strategy and priority override. The suggested extra debt payment is the suggested extra-debt share of your next paycheck: <b>${dollars(budgetAnalysis().allocation?.parts.debt||0)}</b>.</p><p>It is an allocation suggestion, not money moved or a payment already made. Paid-off regular payments roll into the remaining debts in the payoff scenarios.</p><div class="actions strategy-actions">${btn('Change Strategy','debtStrategy')}${btn('Adjust Allocation','allocations')}</div>`);return true;}
 if(action==='debtStrategy'){debtStrategyForm();return true;}
 if(action==='payoffPreview'){payoffPreview();return true;}
 if(action==='hideScenario'){await write('hideScenario',{extra:Number(id)});return true;}
 if(action==='utilization'){show('Custom Utilization Target',input('Target %','target',B.settings.utilizationTarget??20,'number','min="0" max="100" step="0.1" required'),d=>write('utilizationSettings',d));return true;}

 // Goals, wishes and savings
 if(action==='goalSavings'){goalSavingsBreakdown();return true;}
 if(action==='financialGoalProgress'){financialGoalProgressDialog();return true;}
 if(action==='wishSavings'){wishSavingsForecastDialog();return true;}
 if(action==='sinkingSavings'){sinkingFundSavingsForecastDialog();return true;}
 if(action==='incomeHelp'){show('How Estimates Work','<p><strong>Hourly</strong> multiplies your hourly rate, weekly hours and estimated take-home percentage by the pay period. <strong>Typical</strong> averages recent matching deposits; <strong>Cautious</strong> allows for variation. Review unusual deposits in Income History. <strong>Entered</strong> uses your typed amount. Until three deposits on separate dates are available, it uses your entered take-home amount. Estimates never record deposits.</p>');return true;}
 if(action==='needMatchReview'){const c=needMatchCandidates(B,S.asOf).find(c=>c.key===id);if(!c)return true;show('Match Scheduled Need','<p>'+esc(c.bill.name)+' · planned '+dollars(c.bill.amount)+' on '+shortDate(c.bill.date)+'</p><p>Match this to '+esc(c.transaction.name)+' · '+dollars(c.transaction.amount)+' on '+shortDate(c.transaction.date)+'?</p><p>The existing purchase counts once. This clears the scheduled Need without a new charge.</p>'+btn('Confirm Match','needMatchConfirm',c.key)+btn('Not This Purchase','needMatchDismiss',c.key));return true;}
 if(action==='needMatchConfirm'||action==='needMatchDismiss'){await write('needMatch',{key:id,mode:action==='needMatchConfirm'?'confirm':'dismiss'});return true;}
 if(action==='billReviewLater'){await write('billReviewSnooze',{key:id});return true;}
 if(action==='chooseNextTarget'){chooseNextTarget();return true;}
 if(action==='toggleGoals'){showAllGoals=!showAllGoals;await render();return true;}
 if(action==='wishResume'){await write('wishResume',{id});return true;}
 if(action==='targetPriority'){targetPriorityForm(id,list);return true;}
 if(action==='completeTarget'){completeTargetForm(id,list);return true;}
 if(action==='allocations'){allocationForm();return true;}
 if(action==='renewal'){renewalForm(id);return true;}

 // Settings and preferences
 if(action==='settingsPanel'){
  if(!settingsPanelParents[id])return true;
  location.hash='settings/'+(location.hash==='#settings/'+id?settingsPanelParents[id]:id);return true;
 }
 {const forms={wishProtection:wishProtectionForm,overduePreferences:overduePreferencesForm,importPreferences:importPreferencesForm};if(forms[action]){forms[action]();return true;}}
 if(action==='expenseColors'){colorForm();return true;}
 if(action==='cashBuffer'){show('Cash Buffer',input('Protected Cash Buffer','buffer',B.settings.buffer,'number','min="0" step="0.01" required'),d=>write('cashBuffer',d));return true;}
 if(action==='reviewEmail'){reviewEmailForm();return true;}
 if(action==='reportToggle'){const p=B.settings.reviewEmail||{};await write('reviewPreferences',{email:p.email||'',enabled:id==='enabled'?!p.enabled:!!p.enabled,yearly:id==='yearly'?!p.yearly:!!p.yearly});return true;}
 if(action==='smtpSetup'){smtpSetupForm();return true;}
 if(action==='mailTest'){show('Send Test Email','<p>Send a short test message without budget information. Your email provider must be set up first.</p>'+input('Send To','email',B.settings.reviewEmail?.email||'','email','required'),async d=>{const result=await api('mail/test',d);close();successNotice('Test email accepted for '+result.recipient+'. Check your inbox and spam folder.');});return true;}
 if(action==='systemCheck'){try{const d=await api('history');runtimeCheck='Connected · '+d.backups.length+' saved backups';}catch(e){runtimeCheck='Check failed: '+e.message;}runtimeCheckedAt=new Date().toLocaleString();await render();return true;}

 // Recovery
 if(action==='restorePayment'||action==='restoreBillPayment'){await write(action,{id});return true;}
 if(action==='purgeRecovery'){
  if(!['purgeBill','purgePayment','purgeOccurrence'].includes(list))return true;
  recoveryDeleteDialog(list,id);return true;
 }

 // Insights
 if(['insightSnooze','insightDismiss','insightRestore'].includes(action)){await write('insightState',{id,status:action==='insightSnooze'?'snoozed':action==='insightDismiss'?'dismissed':'reset',until:add(S.asOf,7)});return true;}

 // Buttons handled elsewhere that must not fall through to other listeners
 if(action==='searchBudget'||action==='more')return true;
 return false;
};
